'use strict';
const $=s=>document.querySelector(s), cats=[...new Set(CONTENT.map(p=>p.category))];
const defaults={saved:[],read:[],hidden:[],weights:{},disabled:['Faith'],theme:'dark',notes:{},seen:[],opens:0};
let state;try{state={...defaults,...JSON.parse(localStorage.getItem('arete-v1')||'{}')}}catch{state={...defaults}};
let storageOK=true;function persist(){try{localStorage.setItem('arete-v1',JSON.stringify(state))}catch{storageOK=false;toast('Storage unavailable. Changes will last only for this session.')}}
state.opens++;persist();let tab='discover',category='All',page=0,queue=[],expanded=new Set(),search='',searchResults=[],speaking=0,installPrompt=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allowed=p=>!state.disabled.includes(p.category)&&!state.hidden.includes(p.id);
let discoveryMode='for-you';try{discoveryMode=localStorage.getItem('arete-discovery-mode')||'for-you'}catch{}
const FAVORITE_LIMIT=5;
let favorites=[],focusArticle=null,dailySelection=null,feedStyle='full';
let focusReturnY=0;
try{const raw=JSON.parse(localStorage.getItem('arete-favorites')||'[]');if(Array.isArray(raw))favorites=[...new Set(raw.filter(c=>cats.includes(c)))].slice(0,FAVORITE_LIMIT);feedStyle=localStorage.getItem('arete-feed-style')==='compact'?'compact':'full'}catch{}
function dayKey(d=new Date()){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function dayScore(id,day){let n=2166136261;for(const c of day+'-'+id){n=Math.imul(n^c.charCodeAt(0),16777619)}return (n>>>0)/4294967296}
function readingMinutes(p){return Math.max(1,Math.ceil([p.summary,p.body,p.extra].join(' ').split(/\s+/).length/180))}
function dailyRank(p,day){const weight=Math.max(-4,Math.min(5,Number(state.weights[p.category])||0));return (state.read.includes(p.id)?-40:0)+(favorites.includes(p.category)?6:0)+weight*.8+(state.seen.includes(p.id)?-1.5:0)+(hasVisual(p)?1:0)+dayScore(p.id,day)*3}
function selectDailyArticles(eligible,day){const ranked=eligible.slice().sort((a,b)=>dailyRank(b,day)-dailyRank(a,day)||a.id-b.id);const selected=[],used=new Set();for(const p of ranked){if(!used.has(p.category)){selected.push(p);used.add(p.category)}if(selected.length===3)break}if(selected.length===3&&selected.every(p=>favorites.includes(p.category))){const alternative=ranked.find(p=>!favorites.includes(p.category)&&!state.read.includes(p.id));if(alternative)selected[2]=alternative}if(selected.length<3)for(const p of ranked){if(!selected.includes(p))selected.push(p);if(selected.length===3)break}return selected}
function todayArticles(){const day=dayKey();if(!dailySelection||dailySelection.day!==day){try{const stored=JSON.parse(localStorage.getItem('arete-daily-selection')||'null');if(stored&&stored.day===day&&Array.isArray(stored.ids))dailySelection=stored}catch{}}
const eligible=CONTENT.filter(allowed),ids=new Set(eligible.map(p=>p.id));if(!dailySelection||dailySelection.day!==day||dailySelection.ids.length!==Math.min(3,eligible.length)||new Set(dailySelection.ids).size!==dailySelection.ids.length||dailySelection.ids.some(id=>!ids.has(id))){dailySelection={day,ids:selectDailyArticles(eligible,day).map(p=>p.id)};try{localStorage.setItem('arete-daily-selection',JSON.stringify(dailySelection))}catch{}}return dailySelection.ids.map(id=>eligible.find(p=>p.id===id)).filter(Boolean)}
function dailyEdition(){const items=todayArticles();if(!items.length)return '';const [lead,...rest]=items;const total=items.reduce((n,p)=>n+readingMinutes(p),0);const done=items.filter(p=>state.read.includes(p.id)).length;const date=new Date();const label=date.toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric'});const meta=p=>esc(p.category)+' · '+readingMinutes(p)+' min'+(state.read.includes(p.id)?' · Read':'');return '<section class="daily-edition" aria-label="Your daily edition"><div class="edition-top"><span class="eyebrow">THE DAILY EDITION</span><time datetime="'+esc(dayKey())+'">'+esc(label)+'</time></div><h2>Something worth knowing.</h2><p class="edition-intro">'+items.length+' '+(items.length===1?'story':'stories')+' · About '+total+' min, at your own pace.</p><button class="edition-lead" data-act="focus-article" data-id="'+lead.id+'"><span class="edition-lead-kicker">'+meta(lead)+'</span><strong>'+esc(lead.title)+'</strong><span class="edition-lead-summary">'+esc(lead.summary)+'</span><span class="edition-lead-cta">Read story <span aria-hidden="true">↗</span></span></button>'+rest.map(p=>'<button class="edition-story" data-act="focus-article" data-id="'+p.id+'"><span class="edition-copy"><small>'+meta(p)+'</small><strong>'+esc(p.title)+'</strong></span><span class="edition-arrow" aria-hidden="true">↗</span></button>').join('')+'<p class="edition-note">'+(done===items.length?'You’ve read today’s selection. Revisit any story whenever you like.':'No streaks or pressure. Read one story or explore further.')+'</p><button class="edition-preferences" data-tab="profile">Personalize your edition →</button></section>'}
function compactCard(p){return '<article class="card compact-story" id="post-'+p.id+'">'+(p.photo?photo(p):'')+'<div class="pad"><div class="meta"><span>'+esc(p.category)+(p.video?' · Video':p.photo?' · Image':hasVisual(p)?' · Illustration':'')+'</span><span>'+readingMinutes(p)+' min'+(state.read.includes(p.id)?' · Read':'')+'</span></div><h2>'+esc(p.title)+'</h2><p>'+esc(p.summary)+'</p>'+(!p.photo&&hasVisual(p)?(EXPLAINERS[p.id]?explainer(p):[12,39,46].includes(p.id)?art(p):'<p class="tiny muted">Video available in full article.</p>'):'')+'<div class="actions"><button class="primary" data-act="focus-article" data-id="'+p.id+'">Read full article</button><button data-act="save" data-id="'+p.id+'" aria-pressed="'+state.saved.includes(p.id)+'">'+(state.saved.includes(p.id)?'✓ Saved':'＋ Save')+'</button></div></div></article>'}
function favoriteControls(){return '<div class="card pad"><h2>Favorite topics</h2><p class="muted">Choose up to five. Favorites and your More/Less like this feedback influence daily selections and discovery. Unread ideas and variety receive priority; choices remain on this device.</p><div class="favorite-grid">'+cats.filter(c=>!state.disabled.includes(c)).map(c=>'<button data-act="favorite" data-favorite="'+esc(c)+'" aria-pressed="'+favorites.includes(c)+'">'+esc(c)+(favorites.includes(c)?' ✓':'')+'</button>').join('')+'</div><p class="tiny muted">'+favorites.length+' / '+FAVORITE_LIMIT+' selected · stored locally</p></div>'}

const REVIEW_INTERVALS=[1,3,7,14,30];
let reviewData={},reviewActive=false,reviewQueue=[],reviewAt=0,reviewRevealed=false,reviewCompleted=0;
function cleanReview(data){const ids=new Set(CONTENT.map(p=>String(p.id)));return Object.fromEntries(Object.entries(data&&typeof data==='object'?data:{}).filter(([id,r])=>ids.has(id)&&r&&Number.isInteger(r.level)&&r.level>=0&&r.level<=REVIEW_INTERVALS.length&&typeof r.due==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(r.due)).map(([id,r])=>[id,{level:r.level,due:r.due}]))}
try{reviewData=cleanReview(JSON.parse(localStorage.getItem('arete-review')||'{}'))}catch{}
function reviewPool(){return CONTENT.filter(p=>allowed(p)&&state.saved.includes(p.id))}
function reviewDue(day=dayKey()){return reviewPool().filter(p=>!reviewData[p.id]||reviewData[p.id].due<=day).sort((a,b)=>(reviewData[a.id]?.due||'').localeCompare(reviewData[b.id]?.due||'')||a.id-b.id)}
function afterDays(n,now=new Date()){let d=new Date(now.getFullYear(),now.getMonth(),now.getDate()+n,12);return dayKey(d)}
function reviewRating(id,remembered,now=new Date()){const prev=reviewData[id]?.level||0;const level=remembered?Math.min(prev+1,REVIEW_INTERVALS.length):0;const interval=remembered?REVIEW_INTERVALS[level-1]:1;return {level,due:afterDays(interval,now)}}
function startReview(){reviewQueue=reviewDue().slice(0,5).map(p=>p.id);reviewActive=true;reviewAt=0;reviewRevealed=false;reviewCompleted=0;render();window.scrollTo(0,0)}
function reviewSummary(){const all=reviewPool(),due=reviewDue(),upcoming=all.map(p=>reviewData[p.id]?.due).filter(d=>d&&d>dayKey()).sort()[0];return '<section class="card pad review-intro"><div class="eyebrow">REMEMBER WHAT MATTERS</div><h2>Review saved ideas</h2><p>Recall an idea before revealing the answer. Review up to five saved originals at a time, at your own pace.</p><p class="muted">'+due.length+' available for review · '+all.length+' eligible saved articles</p>'+(due.length?'<button class="primary" data-act="review-start">Start a short review</button>':all.length?'<p class="tiny muted">Next scheduled review: '+esc(upcoming||'No scheduled date')+'</p>':'<p class="tiny muted">Save an original article to build your review collection.</p>')+'<p class="tiny muted">Optional, stored locally. No streaks or notifications.</p></section>'}
function reviewPanel(){const p=CONTENT.find(x=>x.id===reviewQueue[reviewAt]);if(!p)return '<section class="card pad review-intro"><div class="eyebrow">REVIEW COMPLETE</div><h2>A little learning, remembered.</h2><p>'+reviewCompleted+' ideas reviewed. You can return when you want.</p><button data-act="review-close">Back to saved ideas</button>'+(reviewDue().length?'<button data-act="review-start">Review another short set</button>':'')+'</section>';const q=p.quiz;return '<section class="card pad review-card"><div class="row"><span class="eyebrow">RECALL · '+(reviewAt+1)+' / '+reviewQueue.length+'</span><button class="right" data-act="review-close">Close</button></div><p class="tiny muted">'+esc(p.category)+'</p><h2>'+esc(q?q[0]:p.title)+'</h2><p class="muted">'+(q?'Try to recall the answer before checking.':'Explain the main idea in your own words before checking.')+'</p>'+(reviewRevealed?'<div class="review-answer"><div class="eyebrow">CHECK YOUR RECALL</div><h3>'+esc(q?q[1][q[2]]:p.summary)+'</h3><p>'+esc(q?q[3]:p.body)+'</p>'+(!q&&p.extra?'<p>'+esc(p.extra)+'</p>':'')+'<p class="tiny"><a href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">Original reference ↗</a></p></div><div class="actions"><button data-act="review-rate" data-id="'+p.id+'" data-remembered="no">Review again tomorrow</button><button class="primary" data-act="review-rate" data-id="'+p.id+'" data-remembered="yes">Remembered</button></div>':'<button class="primary" data-act="review-reveal">Reveal answer</button>')+'<p class="tiny muted">Honest self-assessment is more useful than a score.</p></section>'}
function reviewAction(a,b){if(a==='review-start'){startReview();return}if(a==='review-close'){reviewActive=false;reviewQueue=[];render();window.scrollTo(0,0);return}if(a==='review-reveal'&&reviewActive){reviewRevealed=true;refresh();return}if(a==='review-rate'&&reviewActive&&reviewRevealed){const id=Number(b.dataset.id);if(id!==reviewQueue[reviewAt])return;reviewData[id]=reviewRating(id,b.dataset.remembered==='yes');try{localStorage.setItem('arete-review',JSON.stringify(reviewData))}catch{toast('Review progress could not be stored; available for this session only')}reviewCompleted++;reviewAt++;reviewRevealed=false;render();window.scrollTo(0,0)}}

const RELATED_CLUSTERS=[[1,25,34,48,58],[2,77,30],[4,56],[5,29,55],[6,15,26,35],[8,19,33,52,59],[9,17,28,42],[12,69],[20,53],[71,85,170],[74,75,99,142],[92,145,93],[94,131,132],[127,128],[125,126],[105,106],[135,136],[140,151],[173,174]];
const relatedCluster=new Map(RELATED_CLUSTERS.flatMap((ids,i)=>ids.map(id=>[id,i])));
function spaceRelated(posts,gap=5){const pending=posts.slice(),out=[];while(pending.length){const recent=new Set(out.slice(-gap).map(p=>relatedCluster.get(p.id)).filter(x=>x!==undefined));let i=pending.findIndex(p=>!recent.has(relatedCluster.get(p.id)));if(i<0)i=0;out.push(pending.splice(i,1)[0])}return out}
function makeQueue(){const pool=CONTENT.filter(p=>allowed(p)&&(category==='All'||p.category===category)&&(!unreadOnly||!state.read.includes(p.id))&&(focusView!=='quiz'||p.quiz)&&(focusView!=='new'||p.id>=185)&&(focusView!=='revised'||p.editorialReview?.status==='source-aligned revision')&&(focusView!=='visual'||hasVisual(p))&&(discoveryMode!=='visual'||hasVisual(p)));let groups={};for(const p of pool){let w=Math.max(-4,Math.min(5,state.weights[p.category]||0));let score=(state.read.includes(p.id)?-20:0)+(state.seen.includes(p.id)?-7:0)+(discoveryMode==='surprise'?0:w*2+(favorites.includes(p.category)?7:0))+Math.random()*(discoveryMode==='surprise'?12:5)+(p.id>=185&&!state.seen.includes(p.id)?12:0)+(discoveryMode==='visual'&&p.photo?4:0);(groups[p.category]??=[]).push({p,score})}for(const g of Object.values(groups))g.sort((a,b)=>b.score-a.score);let out=[],last='';while(Object.values(groups).some(g=>g.length)){let options=Object.entries(groups).filter(([k,g])=>g.length).sort((a,b)=>b[1][0].score-a[1][0].score);let next=options.find(([k])=>k!==last)||options[0];out.push(next[1].shift().p);last=next[0]}queue=focusView==='new'?out.sort((a,b)=>b.id-a.id):spaceRelated(out);page=0}
function toast(s){const el=$('#toast');if(!el)return;el.textContent=s;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',2500)}
function signal(p,n){state.weights[p.category]=Math.max(-4,Math.min(5,(state.weights[p.category]||0)+n));persist()}
function art(p){
const palette={Psychology:['#203d3c','#a8dbd0'],Philosophy:['#413326','#f0c893'],Faith:['#38324e','#d9c7f6'],Science:['#162b44','#a8d2fa'],Learning:['#2d402f','#bce0b0'],Family:['#503630','#f7c5aa'],Finance:['#35402c','#d0df9e'],Character:['#443a2a','#efd09c'],Health:['#193d39','#ace1d4'],Literature:['#482f42','#f0b9d7'],History:['#503824','#eec49a']};
const [bg,ink]=palette[p.category]||palette.Science;let graphic='';
if(p.id===4)graphic='<circle cx="95" cy="74" r="27" fill="#eec376"/><path d="M135 56H228M135 74H228M135 92H228" stroke="#eec376" stroke-width="2" stroke-dasharray="6 5"/><circle cx="278" cy="74" r="29" fill="#26394b" stroke="#dce8f3"/><path d="M278 45a29 29 0 0 0 0 58Z" fill="#e6e9ef"/><circle cx="439" cy="74" r="32" fill="#518bb6"/><text x="95" y="135">Sun</text><text x="278" y="135">Moon</text><text x="439" y="135">Earth</text>';
if(p.id===12)graphic='<circle cx="148" cy="63" r="39" fill="none" stroke="#e6bb7e" stroke-width="2"/><text x="148" y="72" font-size="25">243</text><circle cx="412" cy="63" r="39" fill="none" stroke="#e6bb7e" stroke-width="2"/><text x="412" y="72" font-size="25">225</text><text x="148" y="133">Rotation · Earth days</text><text x="412" y="133">Orbit · Earth days</text>';
if(p.id===39)graphic='<circle cx="145" cy="65" r="23" fill="#6b9eb8"/><path d="M137 47l13 9 8 12-13 12-14-7" fill="#90bc8d"/><circle cx="406" cy="64" r="48" fill="#b79076"/><path d="M365 46H447M360 65H452M370 84H442" stroke="#e9c3a0" stroke-width="9"/><text x="145" y="139">Earth · Rocky</text><text x="406" y="139">Jupiter · Gas giant</text>';
if(p.id===46)graphic='<path d="M96 77Q250 26 498 18Q270 70 96 77Z" fill="#9ac9fa" opacity=".65"/><path d="M96 77Q270 81 498 129Q250 109 96 77Z" fill="#d8ac79" opacity=".7"/><circle cx="96" cy="77" r="24" fill="#d7e4ed" opacity=".4"/><circle cx="96" cy="77" r="10" fill="#f3ead9"/><text x="96" y="132">Nucleus</text><text x="400" y="151">Gas and dust</text>';
if(graphic)return '<figure class="feature-art" style="background:'+bg+';color:'+ink+'"><svg viewBox="0 0 560 165" role="img" aria-label="'+esc(p.visual)+'"><g fill="'+ink+'" font-family="system-ui,sans-serif" font-size="17" text-anchor="middle">'+graphic+'</g></svg><figcaption>Concept illustration · Not to scale</figcaption></figure>';
return '<div class="concept" style="--concept-bg:'+bg+';--concept-ink:'+ink+'"><small>THE CENTRAL IDEA</small><strong>'+esc(p.visual||p.category)+'</strong></div>';
}
const quizAnswers={};
function photo(p){if(!p.photo)return '';const [url,alt,credit,source]=p.photo;return '<figure class="photo"><img loading="lazy" decoding="async" referrerpolicy="no-referrer" src="'+esc(url)+'" alt="'+esc(alt)+'"><figcaption>'+esc(alt)+' · <a href="'+esc(source)+'" target="_blank" rel="noopener noreferrer">'+esc(credit)+'</a></figcaption></figure>'}
function quiz(p){if(!p.quiz)return '';const [question,choices,right,explanation]=p.quiz;const selected=quizAnswers[p.id];return '<section class="quiz"><small>TEST YOUR KNOWLEDGE</small><h3>'+esc(question)+'</h3>'+choices.map((c,i)=>'<button class="quiz-option '+(selected===i?'chosen ':'')+(selected!==undefined&&i===right?'correct':'')+'" data-act="quiz" data-id="'+p.id+'" data-choice="'+i+'" aria-pressed="'+(selected===i)+'">'+esc(c)+'</button>').join('')+(selected!==undefined?'<p class="quiz-answer" role="status"><strong>'+(selected===right?'Correct. ':'Not quite. ')+'</strong>'+esc(explanation)+'</p>':'')+'</section>'}

