function hasVisual(p){return Boolean(p.photo||p.video||EXPLAINERS[p.id]||[12,39,46].includes(p.id))}
function explainer(p){const d=EXPLAINERS[p.id];return d?'<figure class="explain-figure"><div class="explain-title">'+esc(d.title)+'</div><svg viewBox="0 0 320 184" role="img" aria-label="'+esc(d.title)+'" xmlns="http://www.w3.org/2000/svg">'+d.svg+'</svg><figcaption>'+esc(d.caption)+' · Original ARETÉ illustration</figcaption></figure>':''}

function articleParagraphs(value){const text=String(value||'').trim();if(!text)return [];if(text.length<420)return [text];let segments;try{segments=Array.from(new Intl.Segmenter('en',{granularity:'sentence'}).segment(text),s=>s.segment)}catch{return [text]}if(segments.length<3)return [text];let offset=0,best=0,distance=Infinity;for(let i=0;i<segments.length-1;i++){offset+=segments[i].length;const diff=Math.abs(offset-text.length/2);if(offset>=130&&text.length-offset>=130&&diff<distance){best=offset;distance=diff}}return best?[text.slice(0,best).trim(),text.slice(best).trim()]:[text]}
function articleBody(p){return [p.body,p.extra].flatMap(articleParagraphs).map(s=>'<p>'+esc(s)+'</p>').join('')}
function card(p){let open=expanded.has(p.id),saved=state.saved.includes(p.id),read=state.read.includes(p.id),isNew=p.id>50;const mins=Math.max(1,Math.ceil([p.summary,p.body,p.extra].join(' ').split(/\s+/).length/180));let isQuick=p.kind==='Quick discovery';return '<article class="card editorial '+(p.photo?'has-photo ':'')+(isQuick?'quick ':'')+(isNew?'new-story':'')+'" id="post-'+p.id+'">'+(p.photo?photo(p):'')+'<div class="pad"><div class="meta"><span>'+esc(p.category)+' · '+esc(p.kind)+'</span><span>'+mins+' min'+(read?' · Read':'')+'</span></div><h2>'+esc(p.title)+'</h2><p class="summary">'+esc(p.summary)+'</p>'+(p.video?'<div class="video-wrap"><video controls playsinline preload="none" poster="'+esc(p.photo?p.photo[0]:'')+'" src="'+esc(p.video)+'"></video><p class="tiny muted">NASA Scientific Visualization Studio · online video · <a href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">Watch at source</a></p></div>':'')+(!p.photo&&!p.quiz&&[12,39,46].includes(p.id)?art(p):'')+'<div class="article-body">'+articleBody(p)+'</div>'+explainer(p)+quiz(p)+(open&&p.reflection?'<div class="reflect"><small>OPTIONAL REFLECTION</small><br>'+esc(p.reflection)+'</div>':'')+'<a class="source" target="_blank" rel="noopener noreferrer" href="'+esc(p.url)+'">'+esc(p.source)+' · '+esc(p.location||'Read source')+' ↗</a>'+(p.editorialReview?.status==='source-aligned revision'?'<p class="editorial-review-label">Revised '+esc(p.editorialReview.date)+' · editorial review, not independent certification</p>':'')+(p.media?'<a class="media-link" target="_blank" rel="noopener noreferrer" href="'+esc(p.media[2])+'"><small>'+esc(p.media[0])+' · Online</small><strong>'+esc(p.media[1])+' ↗</strong></a>':'')+'<div class="actions main-actions"><button data-act="save" data-id="'+p.id+'" aria-pressed="'+saved+'">'+(saved?'✓ Saved':'＋ Save')+'</button><button data-act="listen" data-id="'+p.id+'">'+(speaking===p.id?'■ Stop':'◖ Listen')+'</button><button data-act="read" data-id="'+p.id+'">'+(read?'✓ Read':'Mark read')+'</button><button data-act="expand" data-id="'+p.id+'" aria-expanded="'+open+'">'+(open?'Close':'••• More')+'</button></div>'+(open?'<div class="details"><div class="actions"><button data-act="share" data-id="'+p.id+'">Share</button><button data-act="more" data-id="'+p.id+'">More like this</button><button data-act="less" data-id="'+p.id+'">Less like this</button><button data-act="hide" data-id="'+p.id+'">Hide</button></div><label class="tiny" for="note-'+p.id+'">Personal note (saved locally)</label><textarea id="note-'+p.id+'" data-note="'+p.id+'" placeholder="What will you remember?">'+esc(state.notes[p.id]||'')+'</textarea><div class="actions"><button data-act="related" data-id="'+p.id+'">Related discoveries →</button></div></div>':'')+'</div></article>'}
const headings={discover:['Discover','Something worth knowing.'],explore:['Explore','Follow your curiosity.'],library:['Library','Go beyond the insight.'],saved:['Saved','Ideas worth returning to.'],profile:['Your space','Make ARETÉ yours.']};
const library=[['Astronomy 2e','OpenStax','https://openstax.org/books/astronomy-2e/pages/preface'],['Noli Me Tangere (The Social Cancer)','José Rizal · Charles Derbyshire translation','https://www.gutenberg.org/ebooks/6737'],['El Filibusterismo (The Reign of Greed)','José Rizal · Charles Derbyshire translation','https://www.gutenberg.org/ebooks/10676'],['Principles of Economics 3e','OpenStax','https://openstax.org/details/books/principles-economics-3e'],['Biology 2e','OpenStax','https://openstax.org/details/books/biology-2e'],['Meditations','Marcus Aurelius','https://classics.mit.edu/Antoninus/meditations.html'],['Enchiridion','Epictetus','https://classics.mit.edu/Epictetus/epicench.html'],['Psychology 2e','OpenStax','https://openstax.org/books/psychology-2e/pages/preface'],['World English Bible','eBible.org','https://ebible.org/eng-web/']];
let voiceChoice='';try{voiceChoice=localStorage.getItem('arete-voice')||''}catch{}
let voiceGeneration=0,narrationSession=null;
const VOICE_RATES=[.8,.92,1,1.15,1.3];
let voiceRate=.92;try{const savedRate=Number(localStorage.getItem('arete-voice-rate'));if(VOICE_RATES.includes(savedRate))voiceRate=savedRate}catch{}
function englishVoices(){try{return window.speechSynthesis?window.speechSynthesis.getVoices().filter(v=>/^en([-_]|$)/i.test(v.lang)):[]}catch{return []}}
function voiceScore(v){return (/natural|neural|enhanced|premium|wavenet/i.test(v.name)?20:0)+(/en[-_]US/i.test(v.lang)?3:0)+(v.localService?1:0)}
function voiceOptions(){return '<option value="">Automatic · best available English voice</option>'+englishVoices().sort((a,b)=>voiceScore(b)-voiceScore(a)).map(v=>'<option value="'+esc(v.voiceURI)+'" '+(voiceChoice===v.voiceURI?'selected':'')+'>'+esc(v.name)+' · '+esc(v.lang)+(v.localService?' · on device':'')+'</option>').join('')}
function narrationChunks(p,max=220){const limit=Math.max(20,Math.floor(Number(max)||220));const chunks=[];for(const part of [p.title,p.summary,p.body,p.extra]){const words=String(part||'').trim().split(/\s+/).filter(Boolean);let chunk='';for(const word of words){if(chunk&&chunk.length+1+word.length>limit){chunks.push(chunk);chunk=''}if(word.length>limit){if(chunk){chunks.push(chunk);chunk=''}chunks.push(word);continue}chunk+=(chunk?' ':'')+word}if(chunk)chunks.push(chunk)}return chunks}
function voiceRateOptions(){return VOICE_RATES.map(rate=>'<option value="'+rate+'" '+(rate===voiceRate?'selected':'')+'>'+rate+'×'+(rate===.92?' · relaxed default':'')+'</option>').join('')}
function narrationPanel(){const s=narrationSession;if(!s)return '';return '<div class="narration-copy"><small>'+ (s.paused?'PAUSED':'NOW READING')+' · '+(s.index+1)+' / '+s.chunks.length+' segments</small><strong>'+esc(s.title)+'</strong></div><div class="narration-actions"><button data-act="narration-toggle">'+(s.paused?'Resume':'Pause')+'</button><button data-act="narration-stop">Stop</button></div>'}
function paintNarration(){const dock=document.getElementById('narration-dock');if(dock){dock.hidden=!narrationSession;dock.innerHTML=narrationPanel()}document.body.classList.toggle('narration-active',!!narrationSession)}
function stopNarration(update=true){++voiceGeneration;narrationSession=null;speaking=0;try{window.speechSynthesis?.cancel()}catch{}if(update)refresh()}
function playNarrationSegment(){const s=narrationSession;if(!s||s.paused)return;if(s.index>=s.chunks.length){stopNarration();return}const token=++voiceGeneration;try{const u=new SpeechSynthesisUtterance(s.chunks[s.index]);u.lang=s.voice?s.voice.lang:'en-US';if(s.voice)u.voice=s.voice;u.rate=s.rate;u.pitch=1;u.onend=()=>{if(token!==voiceGeneration||narrationSession!==s||s.paused)return;s.index++;playNarrationSegment()};u.onerror=()=>{if(token!==voiceGeneration||narrationSession!==s)return;stopNarration();toast('Narration unavailable. Try another device voice in Profile.')};paintNarration();window.speechSynthesis.speak(u)}catch{stopNarration();toast('Narration unavailable on this device.')}}
function toggleNarration(){const s=narrationSession;if(!s)return;if(s.paused){s.paused=false;playNarrationSegment()}else{s.paused=true;++voiceGeneration;try{window.speechSynthesis.cancel()}catch{}paintNarration()}}
function speakPost(p){activeHumanTrack=null;const human=document.getElementById('human-player');if(human&&typeof human.pause==='function')human.pause();if(!p||!window.speechSynthesis||typeof SpeechSynthesisUtterance!=='function'){toast('Text-to-speech is not available on this device.');return}const chunks=narrationChunks(p);if(!chunks.length)return;stopNarration(false);const voices=englishVoices();const chosen=voices.find(v=>v.voiceURI===voiceChoice)||voices.sort((a,b)=>voiceScore(b)-voiceScore(a))[0];narrationSession={id:p.id,title:p.title,chunks,index:0,paused:false,voice:chosen,rate:voiceRate};speaking=p.id;playNarrationSegment();refresh()}
if(window.speechSynthesis?.addEventListener)window.speechSynthesis.addEventListener('voiceschanged',()=>{let s=document.getElementById('voice-choice');if(s)s.innerHTML=voiceOptions()});


let webItems=[],webDate='',webStatus='',webSeeded='',webExpanded=false,webFilter='all',webBusy=false;
try{const prior=JSON.parse(localStorage.getItem('arete-web')||'{}');webItems=Array.isArray(prior.items)?prior.items:[];webDate=prior.updated||'';webSeeded=prior.seeded||''}catch{}
function trustedWebItem(p){try{const u=new URL(p.url);return typeof p.title==='string'&&p.title.length>0&&p.title.length<500&&u.protocol==='https:'&&!u.username&&!u.password&&['www.nasa.gov','science.nasa.gov','blogs.loc.gov','www.loc.gov','www.smithsonianmag.com','smithsonianmag.com','www.science.org'].includes(u.hostname)}catch{return false}}
function webTopic(p){const s=String(p.source||'');return s.includes('NASA')?'space':s.includes('Smithsonian Science')?'nature':s.includes('Smithsonian History')||s.includes('Library of Congress')?'history':'other'}
function educationalHeadline(p){return !/\b(supplier program|mentor.prot.g.|budget analyst|cinema|press conference|media advisory|contract award|administrator statement|job opening|procurement)\b/i.test(p.title)}
function digestItems(items,filter,expanded){const unique=[...new Map(items.filter(trustedWebItem).map(p=>[p.url,p])).values()];let filtered=unique.filter(p=>filter==='all'||filter==='all-headlines'||webTopic(p)===filter);if(filter!=='all-headlines')filtered=filtered.filter(educationalHeadline);if(filter==='all'){const groups={space:[],nature:[],history:[],other:[]};for(const p of filtered)groups[webTopic(p)].push(p);filtered=[];while(Object.values(groups).some(g=>g.length))for(const k of ['space','nature','history','other'])if(groups[k].length)filtered.push(groups[k].shift())}return {total:filtered.length,items:filtered.slice(0,expanded?50:4)}}
function freshSection(){const list=digestItems(webItems,webFilter,webExpanded),filters=[['all','For you'],['space','Space'],['nature','Nature & science'],['history','History & culture'],['all-headlines','All headlines']];return '<section class="web-digest" id="web-digest"><div class="row"><div><div class="eyebrow">LATEST FROM PUBLISHERS</div><h2>From the web</h2></div><button class="right" data-act="fresh" '+(webBusy?'disabled':'')+'>'+(webBusy?'Checking…':'Refresh')+'</button></div><p class="tiny muted">'+esc(webStatus||(webDate?'Last automatic refresh: '+webDate.slice(0,10):webSeeded?'Selected links · '+webSeeded:'Publisher headlines · online reading'))+'</p><div class="web-filters" aria-label="Headline topics">'+filters.map(([key,label])=>'<button data-act="web-filter" data-filter="'+key+'" aria-pressed="'+(key===webFilter)+'">'+label+'</button>').join('')+'</div><p class="tiny muted">'+list.total+' matching publisher links · source articles open online</p>'+(list.items.length?list.items.map(p=>'<a class="web-item" href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer"><small>'+esc(p.source||'Publisher')+' · '+esc(p.date||'')+'</small><strong>'+esc(p.title)+'</strong><span>Read original ↗</span></a>').join(''):'<p>No matching stories available. Try another topic or refresh while online.</p>')+(list.total>4?'<button class="web-expand" data-act="web-more">'+(webExpanded?'Show fewer headlines':'See more headlines')+'</button>':'')+'</section>'}
function paintDigest(){const el=document.getElementById('web-digest');if(el)el.outerHTML=freshSection();else if(tab==='explore'&&search.trim()&&!searchDetail)paintSearch()}
async function refreshWeb(show){if(webBusy)return;webBusy=true;if(show){webStatus='';paintDigest()}try{let j;for(const url of ['https://raw.githubusercontent.com/nicejuann/arete/main/fresh.json','./fresh.json']){try{const r=await fetch(url,{cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)continue;const candidate=await r.json();if(Array.isArray(candidate.items)&&candidate.items.some(trustedWebItem)){j=candidate;break}}catch{}}if(!j)throw Error('Feed unavailable');const candidateDate=j.updated||j.seeded||'',existingDate=webDate||webSeeded||'';if(!existingDate||candidateDate>=existingDate||!webItems.length){webItems=j.items.filter(trustedWebItem).slice(0,50);webDate=j.updated||'';webSeeded=j.seeded||'';try{localStorage.setItem('arete-web',JSON.stringify({items:webItems,updated:webDate,seeded:webSeeded}))}catch{}}webStatus=''}catch{webStatus='Could not refresh. Previously available headlines are retained.'}finally{webBusy=false;paintDigest()}}


let openItems=[],openSaved=[],openDate='',openStatus='',openBusy=false,openLimit=1,openCategory='all';
try{const v=JSON.parse(localStorage.getItem('arete-open-reading')||'{}');openItems=Array.isArray(v.items)?v.items:[];openDate=v.updated||'';openSaved=JSON.parse(localStorage.getItem('arete-open-saved')||'[]');if(!Array.isArray(openSaved))openSaved=[]}catch{}
function validOpen(p){try{const u=new URL(p.url),rev=new URL(p.revision),hist=new URL(p.history);return /^wiki-\d+$/.test(p.id)&&typeof p.title==='string'&&p.title.length<=160&&cats.includes(p.category)&&typeof p.text==='string'&&p.text.length<=2600&&p.text.split(/\s+/).length>=100&&p.license==='CC BY-SA 4.0'&&p.licenseUrl==='https://creativecommons.org/licenses/by-sa/4.0/'&&[u,rev,hist].every(v=>v.protocol==='https:'&&v.hostname==='en.wikipedia.org'&&!v.username&&!v.password)&&u.pathname.startsWith('/wiki/')&&rev.pathname==='/w/index.php'&&hist.pathname==='/w/index.php'}catch{return false}}
function openCard(p){const saved=openSaved.some(x=>x.id===p.id);return '<article class="open-article"><div class="eyebrow">'+esc(p.category)+' · OPEN READING · '+Math.max(1,Math.ceil(p.text.split(/\s+/).length/180))+' MIN</div><h3>'+esc(p.title)+'</h3><div class="open-text">'+p.text.split(/\n\s*\n/).map(t=>'<p>'+esc(t)+'</p>').join('')+'</div><div class="open-credit">Excerpt from <a target="_blank" rel="noopener noreferrer" href="'+esc(p.url)+'">English Wikipedia</a> by its <a target="_blank" rel="noopener noreferrer" href="'+esc(p.history)+'">contributors</a>. <a target="_blank" rel="noopener noreferrer" href="'+esc(p.revision)+'">Source revision</a> · <a target="_blank" rel="noopener noreferrer" href="'+esc(p.licenseUrl)+'">CC BY-SA 4.0</a>. Plain text, shortened; not independently reviewed. See source for any additional attribution.</div><button class="open-save" data-act="open-save" data-open-id="'+esc(p.id)+'" aria-pressed="'+saved+'">'+(saved?'✓ Saved':'＋ Save excerpt')+'</button></article>'}
function openReadingSection(){const pool=openItems.filter(validOpen).filter(p=>!state.disabled.includes(p.category)&&(openCategory==='all'||p.category===openCategory));let group={};for(const p of pool)(group[p.category]??=[]).push(p);let balanced=[];while(Object.values(group).some(g=>g.length))for(const g of Object.values(group))if(g.length)balanced.push(g.shift());const available=[...new Set(openItems.filter(validOpen).filter(p=>!state.disabled.includes(p.category)).map(p=>p.category))];return '<section class="open-reading" id="open-reading"><div class="row"><div><div class="eyebrow">OPEN-LICENSE EDUCATIONAL READING</div><h2>Beyond the headline</h2></div><button class="right" data-act="open-refresh" '+(openBusy?'disabled':'')+'>'+(openBusy?'Checking…':'Refresh')+'</button></div><p class="tiny muted">'+esc(openStatus||(openDate?'Collection updated '+openDate.slice(0,10):'Awaiting the first automated import.'))+' · '+pool.length+' excerpts · publisher text, not ARETÉ originals.</p><div class="web-filters">'+['all',...available].map(c=>'<button data-act="open-filter" data-open-cat="'+esc(c)+'" aria-pressed="'+(openCategory===c)+'">'+esc(c==='all'?'All topics':c)+'</button>').join('')+'</div>'+(balanced.length?balanced.slice(0,openLimit).map(openCard).join(''):'<p>No open-reading excerpts available for this selection yet. Your original ARETÉ library remains available.</p>')+(balanced.length>openLimit?'<button class="web-expand" data-act="open-more">Read more excerpts</button>':'')+(openLimit>1?'<button class="web-expand" data-act="open-less">Show one excerpt</button>':'')+'</section>'}
function paintOpen(){const e=document.getElementById('open-reading');if(e)e.outerHTML=openReadingSection();else if(tab==='explore'&&search.trim()&&!searchDetail)paintSearch()}
async function refreshOpen(){if(openBusy)return;openBusy=true;openStatus='';paintOpen();try{let found;for(const url of ['./open-reading.json','https://raw.githubusercontent.com/nicejuann/arete/main/open-reading.json']){try{const r=await fetch(url,{cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)continue;const j=await r.json();if(Array.isArray(j.items)&&j.items.some(validOpen)&&(!found||(j.updated||'')>(found.updated||'')))found=j}catch{}}if(found){if(!openDate||(found.updated||'')>=openDate||!openItems.length){openItems=found.items.filter(validOpen).slice(0,100);openDate=found.updated||'';try{localStorage.setItem('arete-open-reading',JSON.stringify({items:openItems,updated:openDate}))}catch{openStatus='Collection loaded; device storage unavailable.'}}}else{openStatus=openItems.length?'Could not retrieve a newer collection; cached excerpts retained.':'First automated import not available yet.'}}finally{openBusy=false;paintOpen()}}
function openAction(a,b){if(a==='open-refresh'){refreshOpen();return}if(a==='open-filter'){openCategory=b.dataset.openCat;openLimit=1;paintOpen();return}if(a==='open-more'){openLimit+=6;paintOpen();return}if(a==='open-less'){openLimit=1;paintOpen();return}if(a==='open-save'){const id=b.dataset.openId;const before=openSaved;const p=openItems.find(x=>x.id===id&&validOpen(x));if(openSaved.some(x=>x.id===id))openSaved=openSaved.filter(x=>x.id!==id);else if(p)openSaved=[...openSaved,p];try{localStorage.setItem('arete-open-saved',JSON.stringify(openSaved))}catch{openSaved=before;toast('Storage unavailable');return}if(tab==='saved')refresh();else if(tab==='explore'&&searchDetail)paintSearch();else paintOpen();toast(openSaved.some(x=>x.id===id)?'Excerpt saved':'Excerpt removed')}}


let galleryItems=[],galleryDate='',galleryBusy=false,galleryStatus='',galleryPage=0;
try{const d=JSON.parse(localStorage.getItem('arete-gallery')||'{}');galleryItems=Array.isArray(d.items)?d.items:[];galleryDate=d.updated||''}catch{}
function validGallery(p){try{const image=new URL(p.image),url=new URL(p.url);return /^met-\d+$/.test(p.id)&&typeof p.title==='string'&&p.title.length>0&&p.title.length<=200&&p.license==='CC0'&&p.licenseUrl==='https://creativecommons.org/publicdomain/zero/1.0/'&&image.protocol==='https:'&&image.hostname==='images.metmuseum.org'&&!image.username&&!image.password&&url.protocol==='https:'&&['www.metmuseum.org','metmuseum.org'].includes(url.hostname)&&!url.username&&!url.password&&url.pathname.replace(/\/$/,'')==='/art/collection/search/'+p.id.slice(4)}catch{return false}}
function galleryCard(p){const info=[p.artist,p.date,p.culture,p.medium].filter(x=>typeof x==='string'&&x.trim());return '<article class="museum-card"><figure class="photo"><img loading="lazy" decoding="async" referrerpolicy="no-referrer" src="'+esc(p.image)+'" alt="'+esc(p.title)+'"><figcaption>'+esc(p.credit||'The Metropolitan Museum of Art')+' · <a href="'+esc(p.licenseUrl)+'" target="_blank" rel="noopener noreferrer">CC0</a></figcaption></figure><div class="museum-pad"><div class="eyebrow">FROM THE MET COLLECTION</div><h3>'+esc(p.title)+'</h3><p>'+esc(info.join(' · ')||'Museum collection record')+'</p><a href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">Explore the artwork at The Met ↗</a></div></article>'}
function starterGallery(){return CONTENT.filter(p=>p.category==='Art'&&p.photo&&p.photo[2].includes('CC0')).map(p=>{const match=/\/art\/collection\/search\/(\d+)$/.exec(p.url);return match?{id:'met-'+match[1],title:p.photo[1],artist:'',date:'',medium:'',credit:p.photo[2],image:p.photo[0],url:p.url,license:'CC0',licenseUrl:'https://creativecommons.org/publicdomain/zero/1.0/'}:null}).filter(p=>p&&validGallery(p))}
function gallerySection(){if(state.disabled.includes('Art'))return '';const imported=galleryItems.filter(validGallery);const pool=imported.length?imported:starterGallery(),n=Math.min(pool.length,6*(galleryPage+1));return '<section class="gallery-section" id="museum-gallery"><div class="row"><div><div class="eyebrow">OPEN ACCESS · CC0</div><h2>Museum discoveries</h2></div><button class="right" data-act="gallery-refresh" '+(galleryBusy?'disabled':'')+'>'+(galleryBusy?'Checking…':'Refresh')+'</button></div><p class="tiny muted">'+esc(imported.length?(galleryStatus||('Collection updated '+galleryDate.slice(0,10))):'Starter gallery from curated Art · automated import not confirmed')+' · '+pool.length+' artworks · '+(imported.length?'museum metadata':'existing curated artwork records')+'.</p>'+(pool.length?'<div class="museum-grid">'+pool.slice(0,n).map(galleryCard).join('')+'</div>':'<p>No imported artworks yet. The curated Art category remains available.</p>')+(n<pool.length?'<button class="web-expand" data-act="gallery-more">Discover 6 more artworks</button>':'')+'</section>'}
function paintGallery(){const e=document.getElementById('museum-gallery');if(e)e.outerHTML=gallerySection();else if(tab==='explore'&&search.trim()&&!searchDetail)paintSearch()}
async function refreshGallery(){if(galleryBusy)return;galleryBusy=true;galleryStatus='';paintGallery();try{let found;for(const url of ['./gallery.json','https://raw.githubusercontent.com/nicejuann/arete/main/gallery.json']){try{const r=await fetch(url,{cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)continue;const j=await r.json();if(Array.isArray(j.items)&&j.items.some(validGallery)&&(!found||(j.updated||'')>(found.updated||'')))found=j}catch{}}if(found&&(!galleryDate||(found.updated||'')>=galleryDate||!galleryItems.length)){galleryItems=found.items.filter(validGallery).slice(0,120);galleryDate=found.updated||'';try{localStorage.setItem('arete-gallery',JSON.stringify({items:galleryItems,updated:galleryDate}))}catch{galleryStatus='Gallery loaded; device storage unavailable.'}}else if(!found)galleryStatus=galleryItems.length?'Using previously collected artwork records.':'First automated artwork collection not available yet.'}finally{galleryBusy=false;paintGallery()}}
const LISTENING=[['Meditations','Marcus Aurelius','LibriVox volunteer narrators','https://librivox.org/the-meditations-of-marcus-aurelius/'],['The Enchiridion','Epictetus','John Pederson · 47 min','https://librivox.org/the-enchiridion-by-epictetus/'],['The Republic','Plato','Bob Neufeld · complete audiobook','https://librivox.org/the-republic-version-2-by-plato/'],['Noli Me Tangere','José Rizal','LibriVox audiobook','https://librivox.org/noli-me-tangere-by-jose-rizal/'],['El Filibusterismo','José Rizal','LibriVox audiobook','https://librivox.org/el-filibusterismo-by-jose-rizal/']];
