let shelf=[],readerPositions={},activeBook=null;
try{shelf=JSON.parse(localStorage.getItem('arete-shelf')||'[]');if(!Array.isArray(shelf))shelf=[];readerPositions=JSON.parse(localStorage.getItem('arete-positions')||'{}')||{}}catch{}
function shelfSave(){try{localStorage.setItem('arete-shelf',JSON.stringify(shelf));return true}catch{toast('Device storage is full; the book could not be saved.');return false}}
function bookList(){return [...shelf,...(state.disabled.includes('Faith')?[]:scripture)]}
function bookPages(b){if(!b)return [];const blocks=b.text.replace(/\r\n/g,'\n').split(/\n{2,}/).flatMap(t=>t.length>2200?t.match(/[\s\S]{1,1800}/g)||[]:[t]);let out=[],buf='';for(const s of blocks){if(buf&&(buf.length+s.length>2500)){out.push(buf);buf=''}buf+=(buf?'\n\n':'')+s}if(buf)out.push(buf);return out.length?out:['']}
function bookSectionIndex(b){return Math.max(0,Math.min(bookPages(b).length-1,Math.floor(Number(readerPositions[b.id])||0)))}
function bookSectionLabel(b){return 'Section '+(bookSectionIndex(b)+1)+' of '+bookPages(b).length}
function bookSearchHits(b,query){const q=String(query||'').trim().toLowerCase();if(!q)return [];return bookPages(b).map((text,index)=>({text,index})).filter(x=>x.text.toLowerCase().includes(q)).slice(0,30).map(x=>{const at=Math.max(0,x.text.toLowerCase().indexOf(q)-35);return {index:x.index,preview:x.text.slice(at,at+125)}})}
function paintBookSearch(query){const target=document.getElementById('book-search-results'),book=bookList().find(b=>b.id===activeBook);if(!target||!book)return;const q=String(query||'').trim(),hits=bookSearchHits(book,q);target.innerHTML=!q?'':hits.length?'<p class="tiny muted">'+hits.length+' matching sections (up to 30 shown)</p>'+hits.map(h=>'<button class="book-hit" data-act="book-jump" data-section="'+h.index+'"><strong>Section '+(h.index+1)+'</strong><small>'+esc(h.preview)+'</small></button>').join(''):'<p class="tiny muted">No matching sections.</p>'}
function jumpBook(index){const book=bookList().find(b=>b.id===activeBook);if(!book||!Number.isInteger(index)||index<0||index>=bookPages(book).length)return;readerPositions[book.id]=index;try{localStorage.setItem('arete-positions',JSON.stringify(readerPositions))}catch{toast('Reading position could not be saved.')}render();window.scrollTo(0,0)}
function libraryReader(){let b=bookList().find(x=>x.id===activeBook);if(b){let pages=bookPages(b),n=bookSectionIndex(b);return '<section class="card pad reader"><button data-act="book-close">← Library</button><h2>'+esc(b.title)+'</h2><p class="muted">'+esc(b.author||'Personal text')+'</p><p class="tiny">Section '+(n+1)+' of '+pages.length+'</p><label class="tiny" for="book-section">Jump to section</label><select id="book-section" class="search">'+pages.map((_,i)=>'<option value="'+i+'" '+(i===n?'selected':'')+'>Section '+(i+1)+'</option>').join('')+'</select><label class="tiny" for="book-search">Search inside this book</label><input type="search" id="book-search" class="search" placeholder="Find words or phrases…"><div id="book-search-results"></div><div class="book-progress"><div style="width:'+((n+1)/pages.length*100)+'%"></div></div><div class="book-text">'+esc(pages[n])+'</div><div class="actions"><button data-act="book-prev" '+(n===0?'disabled':'')+'>Previous</button><button data-act="book-next" '+(n===pages.length-1?'disabled':'')+'>Next section</button></div>'+(b.url?'<a class="source" href="'+esc(b.url)+'" target="_blank" rel="noopener noreferrer">Read original source ↗</a>':'')+'</section>'}
return '<section class="card pad"><div class="eyebrow">Offline reader</div><h2>My reading shelf</h2><p>Import TXT, EPUB or text-based PDF files you have permission to use. Extracted text stays on this device and your last section is remembered.</p><button class="primary" data-act="book-import">＋ Import book</button><input id="book-file" type="file" accept=".txt,.epub,.pdf,text/plain,application/epub+zip,application/pdf" hidden><p class="tiny muted">TXT up to 500 KB; EPUB/PDF up to 15 MB and 500,000 extracted characters. PDF import loads the pinned PDF.js reader online. No OCR, DRM, layout or illustration preservation. Device storage limits apply.</p>'+bookList().map(b=>'<div class="shelf-row"><div><strong>'+esc(b.title)+'</strong><small>'+esc(b.author||'Personal text')+' · '+esc(bookSectionLabel(b))+'</small></div><button data-act="book-open" data-book="'+esc(b.id)+'">'+(bookSectionIndex(b)>0?'Continue':'Read')+'</button>'+(b.id.startsWith('local-')?'<button data-act="book-remove" data-book="'+esc(b.id)+'" aria-label="Remove book">×</button>':'')+'</div>').join('')+(state.disabled.includes('Faith')?'<p class="tiny muted">Enable Faith in Profile to see the two included Psalms.</p>':'<p class="tiny muted">Scripture starter collection: Psalm 1 and Psalm 23 only. <a href="https://ebible.org/eng-web/" target="_blank" rel="noopener noreferrer">Complete Bible online ↗</a></p>')+'</section>'}

const BOOK_LIMIT=500000;
let importingBook=false;
function zipPath(base,href){const raw=decodeURIComponent(href.split('#')[0]);if(!raw||raw.startsWith('/')||raw.includes('\\')||/^[a-z][a-z0-9+.-]*:/i.test(raw))throw Error('Unsupported EPUB path');const parts=base.split('/').slice(0,-1);for(const part of raw.split('/')){if(part==='..'){if(!parts.length)throw Error('Invalid EPUB path');parts.pop()}else if(part&&part!=='.')parts.push(part)}return parts.join('/')}
function epubDirectory(buf){const v=new DataView(buf),bytes=new Uint8Array(buf);let e=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--){if(v.getUint32(i,true)===0x06054b50&&i+22+v.getUint16(i+20,true)===bytes.length){e=i;break}}if(e<0||v.getUint16(e+4,true)||v.getUint16(e+6,true))throw Error('Unsupported ZIP archive');const count=v.getUint16(e+10,true),size=v.getUint32(e+12,true),start=v.getUint32(e+16,true);if(!count||count>10000||start+size>e)throw Error('Invalid or oversized EPUB directory');let entries=new Map(),at=start;const decoder=new TextDecoder('utf-8',{fatal:true});for(let i=0;i<count;i++){if(at+46>e||v.getUint32(at,true)!==0x02014b50)throw Error('Invalid EPUB directory');const flags=v.getUint16(at+8,true),method=v.getUint16(at+10,true),compressed=v.getUint32(at+20,true),plain=v.getUint32(at+24,true),nameLen=v.getUint16(at+28,true),extraLen=v.getUint16(at+30,true),commentLen=v.getUint16(at+32,true),offset=v.getUint32(at+42,true);if(at+46+nameLen+extraLen+commentLen>e)throw Error('Invalid EPUB entry');const name=decoder.decode(bytes.subarray(at+46,at+46+nameLen));if(entries.has(name))throw Error('Duplicate EPUB entry');entries.set(name,{flags,method,compressed,plain,offset});at+=46+nameLen+extraLen+commentLen}return {entries,bytes,v}}
async function epubText(zip,name,maxPlain=5000000){const item=zip.entries.get(name);if(!item||item.flags&1||item.plain>maxPlain||item.compressed>15000000||![0,8].includes(item.method))throw Error('Unsupported, encrypted or oversized EPUB section');const {v,bytes}=zip,o=item.offset;if(o+30>bytes.length||v.getUint32(o,true)!==0x04034b50)throw Error('Invalid EPUB local entry');const start=o+30+v.getUint16(o+26,true)+v.getUint16(o+28,true);if(start+item.compressed>bytes.length)throw Error('Truncated EPUB');let data=bytes.subarray(start,start+item.compressed);if(item.method===8){if(typeof DecompressionStream==='undefined')throw Error('Your browser does not support EPUB decompression');const reader=new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw')).getReader();let pieces=[],total=0;try{while(true){const {value,done}=await reader.read();if(done)break;total+=value.length;if(total>item.plain||total>maxPlain)throw Error('EPUB decompression limit exceeded');pieces.push(value)}}finally{await reader.cancel().catch(()=>{})}data=new Uint8Array(await new Blob(pieces).arrayBuffer())}if(data.length!==item.plain)throw Error('EPUB size mismatch');return new TextDecoder('utf-8',{fatal:true}).decode(data)}
function epubXML(s){if(/<!DOCTYPE|<!ENTITY/i.test(s))throw Error('Unsupported XML declaration');const d=new DOMParser().parseFromString(s,'application/xml');if(d.getElementsByTagName('parsererror').length)throw Error('Invalid EPUB XML');return d}
function xmlElements(d,name){return Array.from(d.getElementsByTagNameNS('*',name))}
function chapterText(doc){const body=xmlElements(doc,'body')[0];if(!body)return '';let parts=[];const blocks=new Set(['p','div','h1','h2','h3','h4','h5','h6','li','blockquote','section','article','br','tr']);const skip=new Set(['script','style','svg','math','nav','iframe','object','audio','video','head']);function visit(n){if(n.nodeType===3){parts.push(n.nodeValue);return}if(n.nodeType!==1||skip.has(n.localName.toLowerCase()))return;const name=n.localName.toLowerCase();if(blocks.has(name))parts.push('\n\n');for(const child of n.childNodes)visit(child);if(blocks.has(name))parts.push('\n\n')}visit(body);return parts.join('').replace(/[ \t]+/g,' ').replace(/\n[ \t]+/g,'\n').replace(/\n{3,}/g,'\n\n').trim()}
async function extractEPUB(file){const zip=epubDirectory(await file.arrayBuffer());if((await epubText(zip,'mimetype')).trim()!=='application/epub+zip')throw Error('Not an EPUB book');const container=epubXML(await epubText(zip,'META-INF/container.xml'));const root=xmlElements(container,'rootfile')[0]?.getAttribute('full-path');if(!root)throw Error('Missing EPUB package');const path=zipPath('',root),opf=epubXML(await epubText(zip,path));const manifest=new Map(xmlElements(opf,'item').map(n=>[n.getAttribute('id'),{href:n.getAttribute('href'),type:n.getAttribute('media-type')}]));const spine=xmlElements(opf,'itemref').filter(n=>n.getAttribute('linear')!=='no');if(!spine.length||spine.length>500)throw Error('Unsupported EPUB spine');const parts=[];let total=0;for(const ref of spine){const item=manifest.get(ref.getAttribute('idref'));if(!item||!item.href||!['application/xhtml+xml','text/html'].includes(item.type))throw Error('Unsupported EPUB reading order');const text=chapterText(epubXML(await epubText(zip,zipPath(path,item.href))));if(text){total+=text.length+2;if(total>BOOK_LIMIT)throw Error('Extracted book exceeds the 500,000-character shelf limit');parts.push(text)}}return parts.join('\n\n')}
