async function importBook(file){if(!file||importingBook)return;const ext=file.name.split('.').pop().toLowerCase();if(!['txt','epub','pdf'].includes(ext)||file.size>(ext==='txt'?500000:15000000)){toast('Choose TXT up to 500 KB, or EPUB/PDF up to 15 MB.');return}importingBook=true;toast('Importing locally…');try{const t=ext==='txt'?await file.text():ext==='epub'?await extractEPUB(file):await extractPDF(file);if(!t.trim()||t.includes('\u0000')||t.length>BOOK_LIMIT)throw Error('No readable text, or extracted text exceeds the shelf limit.');const id='local-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);const b={id,title:file.name.replace(/\.(txt|epub|pdf)$/i,''),author:ext.toUpperCase()+' text · stored locally',text:t};shelf.push(b);if(!shelfSave()){shelf=shelf.filter(x=>x.id!==id);return}activeBook=id;render();window.scrollTo(0,0);toast('Book imported')}catch(e){toast(e.message||'Could not import this book')}finally{importingBook=false}}
function readerAction(a,b){if(a==='book-jump'){jumpBook(Number(b.dataset.section));return}if(a==='book-import'){$('#book-file').click();return}if(a==='book-open'){activeBook=b.dataset.book;render();window.scrollTo(0,0);return}if(a==='book-close'){activeBook=null;render();window.scrollTo(0,0);return}if(a==='book-remove'){if(!confirm('Remove this imported text from your device?'))return;let prev=shelf;shelf=shelf.filter(x=>x.id!==b.dataset.book);if(!shelfSave())shelf=prev;render();return}if(a==='book-next'||a==='book-prev'){const book=bookList().find(x=>x.id===activeBook);if(!book)return;readerPositions[book.id]=Math.max(0,Math.min(bookPages(book).length-1,(Number(readerPositions[book.id])||0)+(a==='book-next'?1:-1)));try{localStorage.setItem('arete-positions',JSON.stringify(readerPositions))}catch{}render();window.scrollTo(0,0)}}


