const PACK_SOURCE='https://ebible.org/Scriptures/engwebp_vpl.zip',PACK_CACHE='scripture-webp-v1',PACK_KEY='./bible-webp.json';
const PACK_CODES='GEN EXO LEV NUM DEU JOS JDG RUT 1SA 2SA 1KI 2KI 1CH 2CH EZR NEH EST JOB PSA PRO ECC SNG ISA JER LAM EZK DAN HOS JOL AMO OBA JON MIC NAM HAB ZEP HAG ZEC MAL MAT MRK LUK JHN ACT ROM 1CO 2CO GAL EPH PHP COL 1TH 2TH 1TI 2TI TIT PHM HEB JAS 1PE 2PE 1JN 2JN 3JN JUD REV'.split(' ');
let biblePack=null,packBusy=false,packStatus='',packRead=false;
function validPack(p){if(!p||p.edition!=='engwebp'||p.source!==PACK_SOURCE||!Array.isArray(p.books)||p.books.length!==66)return false;let count=0;for(let i=0;i<66;i++){let b=p.books[i];if(!b||b.code!==PACK_CODES[i]||!Array.isArray(b.chapters)||b.chapters.length!==BIBLE_BOOKS[i][1])return false;for(const c of b.chapters){if(!validVerses(c)||c.some((v,j)=>v.verse<1||(j>0&&v.verse<=c[j-1].verse)))return false;count+=c.length}}return count>=30000&&count===p.verseCount}

const PACK_ALIASES={EXOD:'EXO',DEUT:'DEU',JOSH:'JOS',JUDG:'JDG',RUTH:'RUT','1SAM':'1SA','2SAM':'2SA','1KGS':'1KI','2KGS':'2KI','1KING':'1KI','2KING':'2KI','1CHR':'1CH','2CHR':'2CH',PS:'PSA',PSALM:'PSA',PSALMS:'PSA',PROV:'PRO',ECCL:'ECC',SOL:'SNG',SONG:'SNG',SOS:'SNG',EZE:'EZK',EZEK:'EZK',JOE:'JOL',JOEL:'JOL',NAH:'NAM',MATT:'MAT',MAR:'MRK',MARK:'MRK',LUKE:'LUK',JOH:'JHN',JOHN:'JHN','1COR':'1CO','2COR':'2CO',PHI:'PHP',PHIL:'PHP','1THESS':'1TH','2THESS':'2TH','1TIM':'1TI','2TIM':'2TI',PHLM:'PHM','1PET':'1PE','2PET':'2PE','1JO':'1JN','2JO':'2JN','3JO':'3JN','1JOHN':'1JN','2JOHN':'2JN','3JOHN':'3JN',JUDE:'JUD',REVELATION:'REV'};
function parseBibleVpl(text){
  if(typeof text!=='string'||text.length>20000000)throw Error('Bible text is too large.');
  const books=PACK_CODES.map((code,i)=>({code,chapters:Array.from({length:BIBLE_BOOKS[i][1]},()=>[])}));
  let count=0;
  for(const line of text.replace(/^\uFEFF/,'').split(/\r?\n/)){
    const m=/^\s*([1-3]?[A-Za-z]+)\s+(\d+):(\d+)\s+(.+)$/.exec(line);
    if(!m){if(/^\s*\S+\s+\d+:\d+/.test(line))throw Error('Malformed verse reference.');continue}
    const code=m[1].toUpperCase(),idx=PACK_CODES.indexOf(PACK_ALIASES[code]||code),ch=Number(m[2]),verse=Number(m[3]);
    if(idx<0||!Number.isInteger(ch)||ch<1||ch>books[idx].chapters.length||verse<1||verse>176||!m[4].trim()||m[4].length>=12000)throw Error('Invalid Bible reference or verse text.');
    const list=books[idx].chapters[ch-1];if(list.some(v=>v.verse===verse))throw Error('Duplicate verse reference.');
    list.push({verse,text:m[4]});count++;
  }
  for(const book of books)for(const chapter of book.chapters)chapter.sort((a,b)=>a.verse-b.verse);
  const p={edition:'engwebp',source:PACK_SOURCE,verseCount:count,books,localImport:true};
  if(!validPack(p))throw Error('Incomplete or invalid archive: expected 66 books, 1,189 nonempty chapters and at least 30,000 verses.');
  return p;
}
async function storeBiblePack(p){
  if(!validPack(p))throw Error('Bible pack failed structural validation.');
  if(!('caches'in window))throw Error('Offline cache is unavailable in this browser.');
  const c=await caches.open(PACK_CACHE);
  await c.put(PACK_KEY,new Response(JSON.stringify(p),{headers:{'Content-Type':'application/json'}}));
  biblePack=p;packRead=true;bibleVerses=null;
  packStatus=p.localImport?'Imported Bible stored offline. Structure checked; source authenticity depends on the archive you selected.':'Complete 66-book Bible saved for offline reading.';
}
async function importBibleArchive(file){
  if(!file||packBusy||bibleBusy)return;
  if(file.size>15000000||!/^engwebp_vpl(?: \(\d+\))?\.zip$/i.test(file.name)){toast('Choose the official engwebp_vpl.zip archive downloaded from eBible.org.');return}
  packBusy=true;packStatus='Validating archive locally…';if(tab==='library')render();
  try{
    const zip=epubDirectory(await file.arrayBuffer()),names=[...zip.entries.keys()].filter(n=>/(^|\/)engwebp_vpl\.txt$/i.test(n));
    if(names.length!==1)throw Error('Expected the official engwebp_vpl.txt entry in the archive.');
    const p=parseBibleVpl(await epubText(zip,names[0],20000000));
    await storeBiblePack(p);
  }catch(e){packStatus=e.message||'Could not import the archive.'}
  finally{packBusy=false;if(tab==='library')render()}
  if(biblePack&&tab==='library'&&bibleOpen&&!bibleBusy)readBible();
}

async function restorePack(){if(packRead)return;packRead=true;try{if(!('caches'in window))return;const c=await caches.open(PACK_CACHE),r=await c.match(PACK_KEY);if(r){const p=await r.json();if(validPack(p)){biblePack=p;if(p.localImport)packStatus='Imported archive · structure checked, source authenticity not independently verified.'}}}catch{packRead=false}}
async function downloadPack(){if(packBusy)return;packBusy=true;packStatus='Downloading and validating the complete Bible…';render();try{if(!('caches'in window))throw Error('Offline cache is unavailable in this browser.');let candidate;for(const url of [PACK_KEY,'https://raw.githubusercontent.com/nicejuann/arete/main/bible-webp.json']){try{const r=await fetch(url,{cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer',signal:AbortSignal.timeout(60000)});if(!r.ok)continue;const raw=await r.text();if(raw.length>15000000)continue;const p=JSON.parse(raw);if(validPack(p)){candidate=p;break}}catch{}}if(!candidate)throw Error('Complete validated Bible pack is not available yet. Use the official offline download link below, or keep reading individual chapters.');await storeBiblePack(candidate)}catch(e){packStatus=e.message||'Download unavailable.'}finally{packBusy=false;if(tab==='library')render()}if(biblePack&&tab==='library'&&bibleOpen&&!bibleBusy)readBible()}
async function removePack(){if(!confirm('Remove the complete offline Bible? Previously cached online chapters will remain.'))return;try{await caches.delete(PACK_CACHE);biblePack=null;packRead=true;bibleVerses=null;packStatus='Complete offline Bible removed.'}catch{packStatus='Could not remove offline Bible.'}render();if(bibleOpen)readBible()}
function packControls(){return '<section class="pack-controls"><strong>Complete offline Bible · WEB Protestant edition</strong><p class="tiny muted">'+(biblePack?'66 books · 1,189 chapters · stored on this device.':'Download the prepared pack when available, or download the official ZIP and import it directly. Previously cached online chapters remain separate.')+'</p><button data-act="'+(biblePack?'bible-pack-remove':'bible-pack-download')+'" '+(packBusy||bibleBusy?'disabled':'')+'>'+(packBusy?'Downloading…':biblePack?'Remove offline Bible':'Download complete Bible')+'</button>'+(!biblePack?'<div class="actions"><a href="'+PACK_SOURCE+'" target="_blank" rel="noopener noreferrer">Download official ZIP ↗</a><button data-act="bible-pack-import" '+(packBusy||bibleBusy?'disabled':'')+'>Import downloaded ZIP</button><input type="file" id="bible-pack-file" accept=".zip,application/zip" hidden></div><p class="tiny muted">Import only the official eBible file. Text is processed on-device; structural checks do not authenticate the source.</p>':'')+'<p class="tiny muted" role="status">'+esc(packStatus)+'</p><a href="https://ebible.org/details.php?id=engwebp" target="_blank" rel="noopener noreferrer">eBible.org · public-domain source ↗</a><br><a href="https://ebible.org/engwebp/" target="_blank" rel="noopener noreferrer">Official offline HTML Bible download ↗</a></section>'}

function bibleKey(){return 'arete-bible-web-'+bibleBook+'-'+bibleChapter}
function bibleView(){if(state.disabled.includes('Faith'))return '';if(!bibleOpen)return '<div class="card pad"><div class="eyebrow">SCRIPTURE · WEB</div><h2>Bible reader</h2><p>Browse 66 books, save chapters offline, or download the complete Protestant edition.</p><button class="primary" data-act="bible-open">Open Bible</button></div>';return '<section class="card pad bible-reader"><div class="row"><h2>World English Bible'+(biblePack?' · Protestant edition':'')+'</h2><button class="right" data-act="bible-close">Close</button></div>'+packControls()+'<div class="bible-controls"><label>Book<select id="bible-book" class="search">'+BIBLE_BOOKS.map(([name],i)=>'<option value="'+i+'" '+(i===bibleBook?'selected':'')+'>'+esc(name)+'</option>').join('')+'</select></label><label>Chapter<select id="bible-chapter" class="search">'+Array.from({length:BIBLE_BOOKS[bibleBook][1]},(_,i)=>'<option value="'+(i+1)+'" '+(i+1===bibleChapter?'selected':'')+'>'+(i+1)+'</option>').join('')+'</select></label></div><button class="primary" data-act="bible-load" '+(bibleBusy?'disabled':'')+'>Read chapter</button><p class="tiny muted" role="status">'+esc(bibleStatus)+'</p><h3>'+esc(BIBLE_BOOKS[bibleBook][0])+' '+bibleChapter+'</h3>'+(bibleVerses?'<div class="bible-verses">'+bibleVerses.map(v=>'<p><sup>'+esc(v.verse)+'</sup> '+esc(v.text.trim())+'</p>').join('')+'</div>':'<p class="muted">Select a chapter and tap Read chapter.</p>')+'<div class="actions"><button data-act="bible-prev" '+(bibleBusy||(bibleBook===0&&bibleChapter===1)?'disabled':'')+'>Previous chapter</button><button data-act="bible-next" '+(bibleBusy||(bibleBook===65&&bibleChapter===BIBLE_BOOKS[bibleBook][1])?'disabled':'')+'>Next chapter</button></div><p class="tiny muted">'+(biblePack?'Public-domain WEB Protestant edition · complete text from eBible.org.':'Online and individually cached WEB chapters · supplied by')+' <a href="https://bible-api.com/" target="_blank" rel="noopener noreferrer">bible-api.com</a>. The complete offline edition is stored separately from individually cached chapters. <a href="https://ebible.org/eng-web/" target="_blank" rel="noopener noreferrer">Alternative Bible website ↗</a></p></section>'}
function validVerses(v){return Array.isArray(v)&&v.length>0&&v.length<=176&&v.every((x,i)=>x&&Number.isInteger(x.verse)&&x.verse>=1&&x.verse<=176&&(i===0||x.verse>v[i-1].verse)&&typeof x.text==='string'&&x.text.trim().length>0&&x.text.length<12000)}
async function readBible(){if(bibleBusy)return;const key=bibleKey(),book=bibleBook,chapter=bibleChapter;bibleBusy=true;try{await restorePack()}finally{bibleBusy=false}if(book!==bibleBook||chapter!==bibleChapter||!bibleOpen||tab!=='library')return;if(biblePack){bibleVerses=biblePack.books[book].chapters[chapter-1];bibleStatus=biblePack.localImport?'Offline imported archive · structure checked':'Complete offline WEB Protestant edition';try{localStorage.setItem('arete-bible-position',JSON.stringify({book,chapter}))}catch{}render();return}try{localStorage.setItem('arete-bible-position',JSON.stringify({book,chapter}));let cached=JSON.parse(localStorage.getItem(key)||'null');if(validVerses(cached)){bibleVerses=cached;bibleStatus='Saved on this device · offline available';render();return}}catch{}if(!navigator.onLine){bibleStatus='This chapter has not been downloaded yet. Connect to the internet.';bibleVerses=null;render();return}bibleBusy=true;bibleStatus='Loading chapter…';bibleVerses=null;render();try{const ref=BIBLE_BOOKS[book][0]+' '+chapter;const response=await fetch('https://bible-api.com/'+encodeURIComponent(ref)+'?translation=web&single_chapter_book_matching=indifferent',{credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error('Unavailable');const j=await response.json();if(!validVerses(j.verses))throw Error('Invalid chapter');const verses=j.verses.map(v=>({verse:v.verse,text:v.text}));let saved=false;try{localStorage.setItem(key,JSON.stringify(verses));saved=true}catch{}if(book===bibleBook&&chapter===bibleChapter){bibleVerses=verses;bibleStatus=saved?'Loaded · saved for offline reading':'Loaded · offline cache unavailable'}}catch{if(book===bibleBook&&chapter===bibleChapter)bibleStatus='Could not load this chapter. Try again later or use the alternative Bible website.'}finally{bibleBusy=false;if(tab==='library')render()}}
function bibleAction(a){if(a==='bible-pack-import'){$('#bible-pack-file').click();return}if(a==='bible-pack-download'){downloadPack();return}if(a==='bible-pack-remove'){removePack();return}if(packBusy)return;if(a==='bible-open'){bibleOpen=true;activeBook=null;readBible();return}if(a==='bible-close'){bibleOpen=false;render();return}if(bibleBusy)return;if(a==='bible-prev'||a==='bible-next'){const step=a==='bible-next'?1:-1;if(step===1&&bibleChapter===BIBLE_BOOKS[bibleBook][1]&&bibleBook<65){bibleBook++;bibleChapter=1}else if(step===-1&&bibleChapter===1&&bibleBook>0){bibleBook--;bibleChapter=BIBLE_BOOKS[bibleBook][1]}else{bibleChapter=Math.min(BIBLE_BOOKS[bibleBook][1],Math.max(1,bibleChapter+step))}bibleVerses=null}readBible()}


let focusView='mix',readingSize='normal',unreadOnly=false,searchScope='all',searchLimit=12,searchDetail=null;
try{focusView=localStorage.getItem('arete-focus-view')||'mix';readingSize=localStorage.getItem('arete-reading-size')||'normal';unreadOnly=localStorage.getItem('arete-unread')==='yes'}catch{}
if(!['mix','original','open','news','gallery','quiz','new','media','revised','visual'].includes(focusView))focusView='mix';
function setPref(k,v){try{localStorage.setItem(k,v)}catch{}}
function discoveryHub(){const choices=[['mix','Discover','A balanced selection'],['original','Originals','Curated insights'],['open','Read','Open readings'],['media','Watch & listen','Audio and video'],['gallery','Gallery','Art and images'],['visual','Visual stories','Images and diagrams'],['quiz','Quizzes','Test understanding'],['new','New articles','Recent additions'],['news','Latest','Publisher headlines'],['revised','Revised reads','Editorial collection']];return '<section class="discovery-collections" aria-label="Choose a collection"><div class="collection-heading"><h2>Explore by interest</h2><p>Choose how you want to learn.</p></div><div class="discovery-hub" aria-label="Discovery collection">'+choices.filter(([k])=>k!=='gallery'||!state.disabled.includes('Art')).map(([k,t,d])=>'<button data-act="focus" data-focus="'+k+'" aria-pressed="'+(focusView===k)+'"><strong>'+esc(t)+'</strong><small>'+esc(d)+'</small></button>').join('')+'</div></section>'}
function focusedFeed(){if(focusView==='media')return mediaPanel();if(focusView==='open')return openReadingSection();if(focusView==='news')return freshSection();if(focusView==='gallery')return gallerySection()||'<p>Enable Art in Profile to browse the gallery.</p>';return ''}
function compactMatch(p,type){const desc=type==='original'?p.summary:type==='open'?p.text.slice(0,145)+'…':type==='gallery'?[p.artist,p.date,p.medium].filter(Boolean).join(' · '):p.source+' · '+p.date;return '<div class="search-hit"><small>'+esc(type==='original'?p.category+' · ARETÉ original':type==='open'?p.category+' · Open reading':type==='gallery'?'Museum · CC0':'Publisher headline')+'</small><strong>'+esc(p.title)+'</strong><p>'+esc(desc||'')+'</p>'+(type==='original'?'<button data-act="search-open" data-id="'+p.id+'">Read full article</button>':type==='open'?'<button data-act="search-excerpt" data-open-id="'+esc(p.id)+'">Read full excerpt</button>':'<a href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">Open source ↗</a>')+'</div>'}

let activeGuide=null,guideArticle=null;
const GUIDE_LIST=[...[{"id":"family","title":"A home that helps children grow","desc":"Responsive relationships, language, play and growing independence.","ids":[6,15,93,134,179,186,189]},{"id":"character","title":"Build character through considered action","desc":"Choice, practical judgment, courage and habits.","ids":[8,23,173,174,181,188]},{"id":"wellbeing","title":"A sustainable approach to well-being","desc":"Physical movement, recovery, sleep and coping with difficulties.","ids":[9,17,103,104,187,185]}],{"id":"water","title":"The hidden physics of water","desc":"From a floating ice cube to deep ocean currents.","ids":[147,148,123,139,140,151]},{"id":"memory","title":"Learn so you can remember","desc":"Attention, retrieval, interference and practice.","ids":[129,65,29,55,152,5]},{"id":"money","title":"Think beyond the price tag","desc":"Opportunity cost, useful purchases, savings and inflation.","ids":[66,61,153,131,133,144]},{"id":"sky","title":"A deeper look at the night sky","desc":"Light, distance, planets and gravitational lenses.","ids":[149,86,122,141,121,69]},{"id":"history","title":"Read history through its sources","desc":"Maps, artifacts, perspective and Philippine history.","ids":[74,75,127,128,99,143]}];
function guidePosts(g){return g.ids.map(id=>CONTENT.find(p=>p.id===id)).filter(p=>p&&allowed(p))}
function guideNext(g){const posts=guidePosts(g);return posts.find(p=>!state.read.includes(p.id))||null}
function guideCatalog(){return '<section class="guide-catalog"><div class="eyebrow">CURATED READING PATHS</div><h2>Ideas that connect</h2><p class="muted">Short, ordered collections. Read at your own pace.</p>'+GUIDE_LIST.map(g=>{const p=guidePosts(g),n=p.filter(x=>state.read.includes(x.id)).length;return p.length?'<button class="guide-entry" data-act="guide-open" data-guide="'+esc(g.id)+'"><span><strong>'+esc(g.title)+'</strong><small>'+esc(g.desc)+'</small><small>'+n+' of '+p.length+' read · '+p.reduce((s,x)=>s+readingMinutes(x),0)+' min total</small></span><span aria-hidden="true">↗</span></button>':''}).join('')+'</section>'}
function guideView(){const g=GUIDE_LIST.find(x=>x.id===activeGuide);if(!g)return guideCatalog();const p=guidePosts(g);if(guideArticle){const current=p.find(x=>x.id===guideArticle);if(current){const next=p[p.indexOf(current)+1];return '<button class="search-back" data-act="guide-index">← '+esc(g.title)+'</button>'+card(current)+(next?'<button class="primary" data-act="guide-read" data-id="'+next.id+'">Next article →</button>':'<button data-act="guide-index">Return to reading path</button>')}guideArticle=null}
const n=p.filter(x=>state.read.includes(x.id)).length;
return '<button class="search-back" data-act="guide-close">← All reading paths</button><section class="card pad guide-detail"><div class="eyebrow">READING PATH</div><h2>'+esc(g.title)+'</h2><p>'+esc(g.desc)+'</p><p class="tiny muted">'+n+' of '+p.length+' marked read</p>'+(guideNext(g)?'<button class="primary guide-resume" data-act="guide-read" data-id="'+guideNext(g).id+'">'+(n?'Continue with next unread':'Start reading path')+' →</button>':'<p class="muted">All available readings marked read. Revisit any below.</p>')+'<div class="book-progress"><div style="width:'+(p.length?100*n/p.length:0)+'%"></div></div>'+p.map((x,i)=>'<button class="guide-entry" data-act="guide-read" data-id="'+x.id+'"><span><small>'+String(i+1).padStart(2,'0')+' · '+esc(x.category)+' · '+readingMinutes(x)+' min</small><strong>'+esc(x.title)+'</strong></span><span aria-hidden="true">'+(state.read.includes(x.id)?'✓':'↗')+'</span></button>').join('')+'<p class="tiny muted">Progress uses your existing Mark read action. No extra tracking.</p></section>'}

function searchText(s){return String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim()}
function unifiedSearch(){let q=searchText(search);if(!q&&activeGuide)return guideView();if(!q)return guideCatalog()+'<h2 class="section-label">Browse by topic</h2><div class="topic-grid">'+cats.filter(c=>!state.disabled.includes(c)).map(c=>'<button data-category="'+esc(c)+'">'+esc(c)+'</button>').join('')+'</div><h2 class="section-label">Explore collections</h2><div class="topic-grid">'+[['open','Open reading'],['news','Latest discoveries'],['gallery','Museum gallery'],['quiz','Knowledge checks']].filter(([k])=>k!=='gallery'||!state.disabled.includes('Art')).map(([k,t])=>'<button data-act="focus" data-focus="'+k+'">'+t+'</button>').join('')+'</div>';
if(searchDetail){let p=searchDetail.type==='original'?CONTENT.find(x=>x.id===searchDetail.id):openItems.find(x=>x.id===searchDetail.id&&validOpen(x));if(p)return '<button class="search-back" data-act="search-back">← Search results</button>'+(searchDetail.type==='original'?card(p):openCard(p));searchDetail=null}
const includes=(...v)=>{const text=searchText(v.join(' '));return q.split(' ').every(word=>text.includes(word))};
const matches=[...CONTENT.filter(p=>allowed(p)&&includes(p.title,p.category,p.summary,p.body,p.extra)).map(p=>[p,'original']),...openItems.filter(p=>validOpen(p)&&!state.disabled.includes(p.category)&&includes(p.title,p.category,p.text)).map(p=>[p,'open']),...webItems.filter(p=>trustedWebItem(p)&&includes(p.title,p.source)).map(p=>[p,'news']),...(state.disabled.includes('Art')?[]:galleryItems.filter(p=>validGallery(p)&&includes(p.title,p.artist,p.medium,p.culture)).map(p=>[p,'gallery']))];
const rank=p=>{const t=searchText(p.title);return t===q?4:t.startsWith(q)?3:t.includes(q)?2:1};const filtered=matches.filter(([p,t])=>searchScope==='all'||t===searchScope).sort((a,b)=>rank(b[0])-rank(a[0]));
return '<div class="web-filters">'+[['all','All'],['original','Originals'],['open','Open reading'],['news','News'],['gallery','Art']].map(([k,t])=>'<button data-act="search-scope" data-scope="'+k+'" aria-pressed="'+(searchScope===k)+'">'+t+'</button>').join('')+'</div><p class="tiny muted">'+filtered.length+' matching results</p>'+filtered.slice(0,searchLimit).map(([p,t])=>compactMatch(p,t)).join('')+(filtered.length>searchLimit?'<button class="web-expand" data-act="search-more">Show more results</button>':'')}
function paintSearch(){let e=$('#results');if(e)e.innerHTML=unifiedSearch()}

function connectionStatus(){const offline=navigator.onLine===false;const controlled=!!navigator.serviceWorker?.controller;return {offline,controlled,label:offline?'Offline':controlled?'Offline shell active':'Online',description:offline?'Built-in articles, quizzes and locally saved text remain available if the app was cached. Online media and source links need a connection.':controlled?'Service worker is controlling this page. Offline access depends on device storage; external media require internet.':'Offline app shell is not confirmed on this page.'}}
function paintConnection(){const el=document.getElementById('connection-status');if(!el)return;const s=connectionStatus();el.textContent=s.label;el.title=s.description;el.dataset.offline=String(s.offline)}
function systemStatus(){const rows=[['Original articles',CONTENT.length],['Guided reading paths',GUIDE_LIST.length],['Local library books',shelf.length],['Connection',connectionStatus().label],['Editorially revised',CONTENT.filter(p=>p.editorialReview?.status==='source-aligned revision').length+'/'+CONTENT.length],['Publisher headlines',webItems.filter(trustedWebItem).length],['Open-license readings',openItems.filter(validOpen).length],['Imported museum records',galleryItems.filter(validGallery).length]];return '<section class="card pad system-status"><h2>Content & app status</h2>'+rows.map(([name,n])=>'<div class="status-row"><span>'+esc(name)+'</span><strong>'+esc(String(n))+'</strong></div>').join('')+'<p class="tiny muted">'+esc(connectionStatus().description)+'</p><p class="tiny muted">Headlines: '+esc(webDate||'No confirmed refresh')+'<br>Open reading: '+esc(openDate||'No confirmed refresh')+'<br>Gallery: '+esc(galleryDate||'Starter gallery only until automated import succeeds')+'</p><p class="tiny muted">Counts reflect collections loaded on this device. All initial articles and new additions have dated source-aligned editorial records. This is not independent factual certification; external sources and media may still be unavailable.</p><button data-act="refresh-all">Refresh collections</button><p><a href="https://github.com/nicejuann/arete/actions" target="_blank" rel="noopener noreferrer">View automated quality checks ↗</a></p></section>'}
function navIcon(key){const icons={"discover":"<circle cx=\"12\" cy=\"12\" r=\"8.5\"/><path d=\"m15.8 8.2-2.1 5.5-5.5 2.1 2.1-5.5 5.5-2.1Z\"/>","explore":"<circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m16 16 4 4\"/>","library":"<path d=\"M4 5h6v15H4zM14 5h6v15h-6zM7 8v6M17 8v6\"/>","saved":"<path d=\"M6 4h12v16l-6-4-6 4z\"/>","profile":"<circle cx=\"12\" cy=\"8\" r=\"3.5\"/><path d=\"M4.5 21v-2a7.5 7.5 0 0 1 15 0v2\"/>"};return '<svg viewBox="0 0 24 24" width="23" height="23" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+(icons[key]||'')+'</svg>'}
function render(){document.body.classList.toggle('light',state.theme==='light');document.body.classList.toggle('focused-reading',!!focusArticle);document.body.classList.toggle('large-reading',readingSize==='large');const [title,subtitle]=headings[tab];let html=`<div class="eyebrow">A place for curiosity</div><h1>${title}</h1><p class="sub">${subtitle}</p>`;if(tab==='discover'&&focusArticle){const p=CONTENT.find(x=>x.id===focusArticle);if(p&&allowed(p)){html='<div class="focused-top"><button data-act="focus-close">← Back to discovery</button><span class="tiny muted">Focused reading</span></div>'+card(p)+'<div class="end"><button data-act="focus-close">Back to discovery</button></div>'}else{focusArticle=null;return render()}}else if(tab==='discover'){if(focusView==='mix'&&category==='All'&&discoveryMode==='for-you'&&!unreadOnly&&page===0)html+=dailyEdition();html+=discoveryHub();if(['open','news','gallery','media'].includes(focusView)){html+=focusedFeed()}else{html+=`<div class="chips" aria-label="Topics">${['All',...cats.filter(c=>!state.disabled.includes(c))].map(c=>`<button class="chip ${category===c?'active':''}" data-category="${esc(c)}">${c==='All'?'For you':esc(c)}</button>`).join('')}</div>`;html+='<div class="feed-modes" aria-label="Discovery mode">'+[['for-you','For you'],['surprise','Surprise me'],['visual','Visual stories']].map(([key,label])=>'<button data-act="mode" data-mode="'+key+'" aria-pressed="'+(discoveryMode===key)+'">'+label+'</button>').join('')+'</div>';html+='<div class="topic-summary"><span>'+queue.length+' discoveries</span><button data-act="unread" aria-pressed="'+unreadOnly+'">'+(unreadOnly?'Unread only ✓':'All / unread')+'</button><button data-act="shuffle">Shuffle</button></div>';let batch=queue.slice(0,(page+1)*5);if(focusView==='visual')html+='<section class="visual-intro"><h2>Look closer.</h2><p>Original explanatory illustrations work offline. Source photographs and videos may require internet.</p></section>';html+=batch.map((p,i)=>((focusView==='visual'||(feedStyle==='compact'&&focusView!=='quiz'))?compactCard(p):card(p))+(i===0&&focusView==='mix'&&category==='All'&&discoveryMode!=='visual'?openReadingSection():'')+(i===1&&focusView==='mix'&&category==='All'&&discoveryMode!=='visual'?freshSection():'')+(i===2&&focusView==='mix'&&(category==='All'||category==='Art')?gallerySection():'')).join('');if(!batch.length)html+='<p>No discoveries match these filters. Try For you, another topic, or turn off unread-only.</p>';html+=`<div class="end"><h3>${page*5+5>=queue.length?'You’re caught up.':'A moment to pause.'}</h3><p class="muted">Take one idea with you. Continue only if you want to.</p>${page*5+5<queue.length?'<button class="primary" data-act="next">Discover 5 more</button>':''}${page>0?'<button data-act="prev">Show fewer</button>':''}<button data-act="shuffle">New selection</button></div>`}}else if(tab==='explore'){html+=`<label for="search" class="tiny">Search the collection</label><input class="search" id="search" type="search" placeholder="Ideas, topics, keywords…" value="${esc(search)}"><div id="results">${results()}</div>`}else if(tab==='saved'&&reviewActive){html=reviewPanel()}else if(tab==='saved'){html+=reviewSummary();html+=openSaved.filter(validOpen).length?'<section class="open-reading"><h2>Saved open readings</h2>'+openSaved.filter(validOpen).map(openCard).join('')+'</section>':'';html+=state.saved.length?CONTENT.filter(p=>state.saved.includes(p.id)).map(card).join(''):'<div class="card pad">No original ARETÉ insights saved yet.</div>'}else if(tab==='library'){html+=bibleView();if(!bibleOpen)html+=libraryReader();if(!activeBook&&!bibleOpen)html+=listeningSection();if(!activeBook&&!bibleOpen)html+='<p class="muted">Free original reading resources. Links need internet; the built-in discoveries work offline after installation.</p>'+library.filter(x=>x[0]!=='World English Bible'||!state.disabled.includes('Faith')).map(x=>`<div class="card pad"><div class="eyebrow">Original reading</div><h2>${x[0]}</h2><p class="muted">${x[1]}</p><a href="${x[2]}" target="_blank" rel="noopener noreferrer">Open source ↗</a></div>`).join('')+`<div class="card pad"><h3>Educational multimedia</h3><p>Listen to the built-in insights with your device’s text-to-speech. For videos, explore free educational collections online.</p><a href="https://ocw.mit.edu/" target="_blank" rel="noopener noreferrer">MIT OpenCourseWare ↗</a><br><a href="https://www.youtube.com/@TEDEd" target="_blank" rel="noopener noreferrer">TED-Ed video channel ↗</a><p class="tiny muted">External sites may show ads. Selected stories include an in-feed NASA video or links to human-narrated material. TXT, EPUB and text-based PDF import are available above as simplified reading text.</p></div>`}else{html+=`<div class="card pad"><div class="grid"><div><div class="stat">${state.read.length}</div><small>Insights marked read</small></div><div><div class="stat">${state.saved.length}</div><small>Saved ideas</small></div></div><p class="tiny muted">These are local counts, not a measure of your wisdom or social media use.</p></div>${favoriteControls()}${systemStatus()}<div class="card pad"><h2>Topics</h2><p class="muted">Choose what appears in your feed. Faith is optional.</p>${cats.map(c=>`<label class="settings-row">${esc(c)}<input type="checkbox" data-topic="${esc(c)}" ${state.disabled.includes(c)?'':'checked'}></label>`).join('')}</div><div class="card pad"><h2>Reading comfort</h2><label for="feed-style">Discovery feed layout</label><select id="feed-style" class="search"><option value="full" ${feedStyle==='full'?'selected':''}>Full articles</option><option value="compact" ${feedStyle==='compact'?'selected':''}>Compact previews</option></select><label for="reading-size">Article text size</label><select id="reading-size" class="search"><option value="normal" ${readingSize==='normal'?'selected':''}>Standard</option><option value="large" ${readingSize==='large'?'selected':''}>Large</option></select></div><div class="card pad"><h2>Narration</h2><p class="muted">Select an English voice available on your device. Natural voices depend on your phone and may require internet or a free voice download in Android settings.</p><label for="voice-choice" class="tiny">Reading voice</label><select id="voice-choice" class="search">${voiceOptions()}</select><label for="voice-rate" class="tiny">Narration speed</label><select id="voice-rate" class="search">${voiceRateOptions()}</select><p class="tiny muted">Changes apply to the next reading. Pause resumes from the beginning of the current short segment. Device voices may need internet.</p></div><div class="card pad"><h2>Data and app</h2><p>Preferences, notes and imported text stay in this browser. Export data includes your text shelf, reading positions, saved readings, review schedule and reading preferences. Bible caches and downloaded media are not included. Import replaces the data contained in the backup. Keep your backup private. No login, analytics or paid service.</p><div class="actions"><button data-act="export">Export data</button><button data-act="restore">Import data</button><button data-act="resetHidden">Restore hidden posts</button><button data-act="install">Install help</button></div><input type="file" id="import" accept="application/json" hidden><p class="tiny muted">ARETÉ v2.0 RC22 · ${storageOK?'Local storage available':'Storage unavailable'}. Offline mode requires a supported secure origin.</p></div>`}$('#main').innerHTML=html;paintConnection();paintNarration();$('#nav').innerHTML=[['discover','◈','Discover'],['explore','⌕','Explore'],['library','▤','Library'],['saved','♡','Saved'],['profile','⚙','Profile']].map(([t,i,l])=>`<button class="navbtn" data-tab="${t}" ${tab===t?'aria-current="page"':''}><span aria-hidden="true">${navIcon(t)}</span>${l}</button>`).join('');if(tab==='discover'&&!focusArticle&&!['open','news','gallery','media'].includes(focusView)){for(const p of queue.slice(0,(page+1)*5)){if(!state.seen.includes(p.id))state.seen.push(p.id)}persist()}}
function results(){return unifiedSearch()}
function openFocusedArticle(p){if(!p||!allowed(p))return;if(!focusArticle)focusReturnY=Number(window.scrollY)||0;focusArticle=p.id;tab='discover';location.hash='discover';render();window.scrollTo(0,0)}
function closeFocusedArticle(){const y=focusReturnY;focusArticle=null;focusReturnY=0;render();window.scrollTo(0,y)}
function navigate(t){activeHumanTrack=null;mediaPlaying=null;focusArticle=null;focusReturnY=0;reviewActive=false;if(t==='explore')searchDetail=null;if(t!=='library'){activeBook=null;bibleOpen=false}tab=t;location.hash=t;render();window.scrollTo(0,0)}
function refresh(){const y=window.scrollY;render();window.scrollTo(0,y)}

const BACKUP_MAX_BYTES=30000000;
function validImport(o){return o&&typeof o==='object'&&!Array.isArray(o)&&[undefined,2,3].includes(o.backupVersion)&&['saved','read','hidden','seen','disabled'].every(k=>Array.isArray(o[k]))&&['dark','light'].includes(o.theme)&&o.weights&&typeof o.weights==='object'&&!Array.isArray(o.weights)&&o.notes&&typeof o.notes==='object'&&!Array.isArray(o.notes)}
function createBackup(){return {...state,backupVersion:3,personalShelf:shelf,openReadingSaved:openSaved,readerPositions,voiceChoice,voiceRate,discoveryMode,favoriteTopics:favorites,feedStyle,reviewSchedule:reviewData,readingSize,focusView,unreadOnly}}
function prepareRestore(o){
  if(!validImport(o))throw Error('Unsupported or invalid ARETÉ backup.');
  const ids=new Set(CONTENT.map(p=>p.id));
  for(const k of ['saved','read','hidden','seen'])if(o[k].some(id=>!ids.has(id)))throw Error('Backup contains article IDs not available in this version. Update ARETÉ before restoring.');
  const next={...defaults,theme:o.theme,disabled:[...new Set(o.disabled.filter(c=>cats.includes(c)))],weights:Object.fromEntries(cats.map(c=>[c,Math.max(-4,Math.min(5,Number(o.weights[c])||0))])),notes:{},opens:Math.max(0,Number(o.opens)||0)};
  for(const [k,v] of Object.entries(o.notes)){if(!ids.has(Number(k))||typeof v!=='string')throw Error('Backup contains an invalid article note.');next.notes[k]=v}
  for(const k of ['saved','read','hidden','seen'])next[k]=[...new Set(o[k])];
  const values=new Map([['arete-v1',JSON.stringify(next)]]);
  const put=(key,value)=>values.set(key,JSON.stringify(value));
  if('personalShelf'in o){if(!Array.isArray(o.personalShelf))throw Error('Invalid reading shelf.');const seen=new Set();for(const b of o.personalShelf){if(!b||typeof b.id!=='string'||!/^local-[a-z0-9-]+$/i.test(b.id)||seen.has(b.id)||typeof b.title!=='string'||typeof b.text!=='string'||!b.text.trim()||b.text.length>BOOK_LIMIT)throw Error('Invalid or oversized book in backup.');seen.add(b.id)}put('arete-shelf',o.personalShelf.map(b=>({id:b.id,title:b.title,author:typeof b.author==='string'?b.author:'Personal text · stored locally',text:b.text})))}
  if('readerPositions'in o){if(!o.readerPositions||typeof o.readerPositions!=='object'||Array.isArray(o.readerPositions))throw Error('Invalid reading positions.');for(const [k,v] of Object.entries(o.readerPositions))if(!/^(local-[a-z0-9-]+|ps1|ps23)$/i.test(k)||!Number.isInteger(v)||v<0)throw Error('Invalid reading position.');put('arete-positions',o.readerPositions)}
  if('openReadingSaved'in o){if(!Array.isArray(o.openReadingSaved)||o.openReadingSaved.some(p=>!validOpen(p)))throw Error('Invalid saved open reading.');put('arete-open-saved',o.openReadingSaved)}
  if('reviewSchedule'in o){if(!o.reviewSchedule||typeof o.reviewSchedule!=='object'||Array.isArray(o.reviewSchedule))throw Error('Invalid review schedule.');const clean=cleanReview(o.reviewSchedule);if(Object.keys(clean).length!==Object.keys(o.reviewSchedule).length)throw Error('Invalid review entry.');put('arete-review',clean)}
  if('favoriteTopics'in o){if(!Array.isArray(o.favoriteTopics)||o.favoriteTopics.some(c=>!cats.includes(c))||new Set(o.favoriteTopics).size>FAVORITE_LIMIT)throw Error('Invalid favorite topics.');put('arete-favorites',[...new Set(o.favoriteTopics)])}
  for(const [field,key,options] of [['discoveryMode','arete-discovery-mode',['for-you','surprise','visual']],['feedStyle','arete-feed-style',['full','compact']],['readingSize','arete-reading-size',['normal','large']],['focusView','arete-focus-view',['mix','original','open','news','gallery','quiz','new','media','revised','visual']]])if(field in o){if(!options.includes(o[field]))throw Error('Invalid reading preference: '+field);values.set(key,o[field])}
  if('voiceChoice'in o){if(typeof o.voiceChoice!=='string'||o.voiceChoice.length>1000)throw Error('Invalid voice preference.');values.set('arete-voice',o.voiceChoice)}
  if('voiceRate'in o){if(typeof o.voiceRate!=='number'||!VOICE_RATES.includes(o.voiceRate))throw Error('Invalid narration speed.');values.set('arete-voice-rate',String(o.voiceRate))}
  if('unreadOnly'in o){if(typeof o.unreadOnly!=='boolean')throw Error('Invalid unread preference.');values.set('arete-unread',o.unreadOnly?'yes':'no')}
  values.set('arete-daily-selection','null');
  return values;
}
function commitRestore(values,storage){
  const previous=new Map(),written=[];
  try{
    for(const key of values.keys())previous.set(key,storage.getItem(key));
    // Free space held by replaced values first; retain all originals in memory.
    for(const key of values.keys()){written.push(key);storage.removeItem(key)}
    for(const [key,value] of values)storage.setItem(key,value);
    return {ok:true};
  }catch{
    let rollback=true;
    for(const key of written)try{storage.removeItem(key)}catch{rollback=false}
    for(const key of written)try{const v=previous.get(key);if(v!==null)storage.setItem(key,v)}catch{rollback=false}
    return {ok:false,rollback};
  }
}
async function doImport(f){
  if(!f||f.size>BACKUP_MAX_BYTES){toast('Backup is missing or exceeds the 30 MB file limit.');return}
  try{
    const values=prepareRestore(JSON.parse(await f.text()));
    if(!window.confirm('Replace your current ARETÉ saved data with this backup? Export your current data first if you want to keep it.'))return;
    const result=commitRestore(values,localStorage);
    if(!result.ok){toast(result.rollback?'Restore failed; previous data was restored. Free device storage and try again.':'Restore failed and rollback could not be confirmed. Keep your backup file and export current data before further changes.');return}
    // Reload only after all targeted local storage writes succeed.
    location.reload();
  }catch(e){toast(e.message||'Invalid ARETÉ backup. No data changed.')}
}

document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;if(b.id==='theme'){state.theme=state.theme==='dark'?'light':'dark';persist();refresh();return}if(b.dataset.tab){navigate(b.dataset.tab);return}if(b.dataset.category){if(!['original','revised','new','quiz','visual'].includes(focusView))focusView='original';setPref('arete-focus-view',focusView);category=b.dataset.category;makeQueue();navigate('discover');return}let a=b.dataset.act,p=CONTENT.find(x=>x.id===Number(b.dataset.id));if(a&&a.startsWith('review-')){reviewAction(a,b);return}if(a==='focus-article'&&p){openFocusedArticle(p);return}if(a==='focus-close'){closeFocusedArticle();return}if(a==='favorite'){const c=b.dataset.favorite;if(!cats.includes(c)||state.disabled.includes(c))return;if(favorites.includes(c))favorites=favorites.filter(x=>x!==c);else if(favorites.length<FAVORITE_LIMIT)favorites.push(c);else{toast('Choose up to five favorite topics');return}setPref('arete-favorites',JSON.stringify(favorites));dailySelection=null;try{localStorage.removeItem('arete-daily-selection')}catch{}makeQueue();refresh();return}if(a==='guide-open'){activeGuide=b.dataset.guide;guideArticle=null;search='';paintSearch();window.scrollTo(0,0);return}if(a==='guide-read'&&p){const g=GUIDE_LIST.find(x=>x.id===activeGuide);if(!g||!guidePosts(g).some(x=>x.id===p.id))return;guideArticle=p.id;paintSearch();window.scrollTo(0,0);return}if(a==='guide-index'){guideArticle=null;paintSearch();window.scrollTo(0,0);return}if(a==='guide-close'){activeGuide=null;guideArticle=null;paintSearch();return}if(a&&a.startsWith('human-')){humanAudioAction(a,b);return}if(a&&a.startsWith('media-')){activeHumanTrack=null;mediaAction(a,b);return}if(a==='focus'){mediaPlaying=null;if(b.dataset.focus==='gallery'&&state.disabled.includes('Art')){toast('Enable Art in Profile first');return}focusView=b.dataset.focus;setPref('arete-focus-view',focusView);category='All';makeQueue();navigate('discover');return}if(a==='unread'){unreadOnly=!unreadOnly;setPref('arete-unread',unreadOnly?'yes':'no');makeQueue();render();window.scrollTo(0,0);return}if(a==='search-scope'){searchScope=b.dataset.scope;searchLimit=12;searchDetail=null;paintSearch();return}if(a==='search-more'){searchLimit+=12;paintSearch();return}if(a==='search-open'&&p){searchDetail={type:'original',id:p.id};paintSearch();window.scrollTo(0,0);return}if(a==='search-excerpt'){searchDetail={type:'open',id:b.dataset.openId};paintSearch();window.scrollTo(0,0);return}if(a==='search-back'){searchDetail=null;paintSearch();return}if(a==='next'||a==='prev'){if(a==='next'){const y=window.scrollY;page++;render();window.scrollTo(0,y)}else{page=Math.max(0,page-1);render();window.scrollTo(0,0)}return}if(a==='mode'){discoveryMode=b.dataset.mode;try{localStorage.setItem('arete-discovery-mode',discoveryMode)}catch{}makeQueue();render();window.scrollTo(0,0);return}if(a&&a.startsWith('bible-')){bibleAction(a);return}if(a&&a.startsWith('book-')){readerAction(a,b);return}if(a==='refresh-all'){await Promise.all([refreshWeb(true),refreshOpen(),refreshGallery()]);if(tab==='profile')refresh();toast('Collection refresh finished; see individual status');return}if(a==='gallery-refresh'){refreshGallery();return}if(a==='gallery-more'){galleryPage++;paintGallery();return}if(a&&a.startsWith('open-')){openAction(a,b);return}if(a==='web-filter'){if(['all','space','nature','history','all-headlines'].includes(b.dataset.filter)){webFilter=b.dataset.filter;webExpanded=false;paintDigest()}return}if(a==='web-more'){webExpanded=!webExpanded;paintDigest();return}if(a==='fresh'){refreshWeb(true);return}if(a==='shuffle'){makeQueue();render();window.scrollTo(0,0);return}if(a==='export'){let url=URL.createObjectURL(new Blob([JSON.stringify(createBackup(),null,2)],{type:'application/json'}));let link=document.createElement('a');link.href=url;link.download='arete-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(a==='restore'){$('#import').click();return}if(a==='resetHidden'){state.hidden=[];persist();makeQueue();refresh();toast('Hidden posts restored');return}if(a==='install'){if(installPrompt){installPrompt.prompt();installPrompt=null}else toast('In Chrome, open the ⋮ menu and choose Add to Home screen or Install app. HTTPS is required.');return}if(!p)return;if(a==='quiz'&&p.quiz){quizAnswers[p.id]=Number(b.dataset.choice);refresh();return}if(a==='expand'){expanded.has(p.id)?expanded.delete(p.id):expanded.add(p.id);refresh()}if(a==='save'){let on=state.saved.includes(p.id);state.saved=on?state.saved.filter(x=>x!==p.id):[...state.saved,p.id];signal(p,on?-1:1);refresh();toast(on?'Removed from saved':'Saved')}if(a==='read'){if(!state.read.includes(p.id)){state.read.push(p.id);signal(p,1)}if(unreadOnly&&tab==='discover'&&!focusArticle){queue=queue.filter(x=>x.id!==p.id);page=Math.min(page,Math.max(0,Math.ceil(queue.length/5)-1))}refresh();toast('Marked as read')}if(a==='more'||a==='less'){signal(p,a==='more'?2:-2);toast('Preference updated for the next selection')}if(a==='hide'){state.hidden.push(p.id);persist();queue=queue.filter(x=>x.id!==p.id);page=Math.min(page,Math.max(0,Math.ceil(queue.length/5)-1));refresh();toast('Hidden. Restore in Profile.')}if(a==='related'){search=p.category;searchDetail=null;searchScope='all';searchLimit=12;navigate('explore')}if(a==='narration-toggle'){toggleNarration();return}if(a==='narration-stop'){stopNarration();return}if(a==='listen'){if(!p)return;if(speaking===p.id){stopNarration();return}speakPost(p)}if(a==='share'){let text=p.title+'\n'+p.summary+'\n'+p.body+'\n'+(p.extra||'')+'\n'+p.source+' '+p.url;try{if(navigator.share){await navigator.share({title:p.title,text})}else if(navigator.clipboard){await navigator.clipboard.writeText(text);toast('Copied insight')}else{window.prompt('Copy this insight',text)}}catch(err){if(err.name!=='AbortError')toast('Sharing unavailable')}}});
